window.__Q=window.__Q||{};window.__Q["tcm/8/A2"]=[{"q":"尿毒症患者的呼吸系统变化中，最不可能出现的是","o":["Kussmaul呼吸","浅快呼吸","纤维素性肺炎","肺水肿","呼气有氨味"],"a":1,"e":"尿毒症时蓄积的代谢产物刺激呼吸中枢，出现Kussmaul呼吸或潮式呼吸，并可致尿毒症性肺炎（纤维素性肺炎）、肺水肿及呼气带氨味。浅快呼吸多见于肺顺应性下降或胸痛限制呼吸，非尿毒症典型表现。"},{"q":"患者，女，80岁。近三年来，记忆力逐渐下降，经常忘记自己刚刚做过的事情。脑CT发现大脑体积缩小，颈内动脉局部狭窄。患者可能患有","o":["颈动脉粥样硬化致脑萎缩","颈动脉粥样硬化致脑水肿","颈动脉玻璃样变致脑萎缩","风湿性颈动脉炎","风湿性脑病"],"a":0,"e":"颈内动脉起始部粥样斑块致管腔狭窄，脑组织长期慢性缺血而发生脑萎缩，出现记忆力减退乃至痴呆。脑水肿见于急性缺血或梗死早期，与三年渐进性病程不符。"},{"q":"患儿，女，5岁。1天前出现高热、头痛、呕吐、外周血白细胞增高，全身出现黏膜瘀点、瘀斑、周围循环衰竭、同时伴有急性肾上腺衰竭症状。此病人首先怀疑","o":["普通型流脑","暴发型流脑","急性支气管炎","慢性咽炎","脑脓肿"],"a":1,"e":"暴发型流脑以败血症性休克为主，短期内出现广泛皮肤黏膜瘀点瘀斑、周围循环衰竭，可因双侧肾上腺出血坏死形成沃-弗综合征。普通型以脑膜刺激征为主，血压多正常。"},{"q":"患者，女，45岁，体检发现乳腺癌。病检见癌细胞突破基膜进入间质，呈实性条索、小梁或团巢状，无明显腺样结构，实质与间质大致相当，此癌是","o":["导管内癌","小叶原位癌","浸润性小叶癌","神经内分泌癌","非特异型浸润癌"],"a":4,"e":"癌细胞突破基膜向间质浸润，排列成实性条索、团巢而缺乏腺样结构，属乳腺浸润性癌的非特殊类型。导管内癌与小叶原位癌均未突破基膜，不属于浸润癌。"},{"q":"感染性休克患者，其血压进行性下降的机制为","o":["总血容量的减少","毛细血管容量的减少，血浆外渗","体液量的减少","毛细血管容量增加，血浆外渗","容量血管收缩，毛细血管通透性增高"],"a":3,"e":"感染性休克时内毒素使全身毛细血管扩张、容量增大，内皮损伤致血浆外渗，有效循环血量减少、回心血量不足，血压进行性下降。总血容量减少见于失血性休克。"},{"q":"某患者诊断为CRF，以下哪一项不是其出现贫血的原因","o":["EPO减少","体内毒性物质蓄积","胃肠吸收功能减退","红细胞脆性增加","血小板功能亢进"],"a":4,"e":"慢性肾衰竭贫血主要因肾组织破坏使促红细胞生成素减少，毒性物质蓄积抑制骨髓造血，胃肠吸收减退致铁及叶酸缺乏，红细胞脆性增加使其寿命缩短。血小板功能亢进引起出血倾向，不导致贫血。"},{"q":"患者，男，15岁。因外伤致血管破裂，失血约800mL，烦躁不安，面色苍白，四肢湿冷，血压100/84mmHg，现患者可能处于","o":["失血性休克代偿期","失血性休克失代偿期","失血性休克晚期","大失血，但未休克","重度虚脱"],"a":0,"e":"失血量约800ml尚未超过循环血量的20%，交感神经兴奋使心率加快、外周血管收缩，血压尚可维持，属代偿期。失血量超过20%～25%即进入失代偿期而血压下降。"},{"q":"患者，男，30岁。因乙型肝炎行穿刺活检，见肝细胞体积增大，胞质疏松、淡染，肝细胞最有可能的病理变化是","o":["脂肪变","细胞水肿","玻璃样变","黏液样变","淀粉样变"],"a":1,"e":"肝细胞损伤后细胞内水分增多，体积增大、胞质疏松淡染，即细胞水肿，病毒性肝炎时最常见，重者呈气球样变。脂肪变为胞质内脂滴空泡，玻璃样变为胞质内均质红染的Mallory小体。"},{"q":"患者，男，84岁。因肺炎并发中毒性休克和DIC，经抢救无效死亡，解剖后在肺、肾、脑等组织切片中可能见到","o":["白色血栓","红色血栓","混合血栓","透明血栓","延续性血栓"],"a":3,"e":"DIC时微循环毛细血管内形成由纤维蛋白构成的透明血栓，即微血栓，仅在镜下可见。白色血栓见于心瓣膜和动脉，红色血栓见于静脉，混合血栓见于静脉延续性血栓体部。"},{"q":"患者，男，20岁。几天前有淋雨史。两天前突发高烧，全身不适，胸闷，今日突然烦躁不安，面色苍白，四肢厥冷，咳铁锈色痰，急诊入院。查体：体温39.5℃，面色苍白，精神恍惚，颈无抵抗，心率110次/分，血压120/90mmHg。听诊右肺上叶呼吸音减弱，叩诊浊音。胸片右肺上叶纹理增强，淡薄阴影。血常规：白细胞计数明显升高。该患者最可能患的疾病是","o":["急性支气管炎","小叶性肺炎","病毒性肺炎","肺脓肿","大叶性肺炎"],"a":4,"e":"青壮年淋雨后急起寒战高热、胸痛、咳铁锈色痰，伴肺实变体征及白细胞升高，为肺炎链球菌所致大叶性肺炎的典型表现。小叶性肺炎多见于小儿与老人，以细支气管为中心。"},{"q":"某患者，因大出血发生失血性休克，出现面色苍白，四肢湿冷，少尿等临床表现。这些临床表现的病理生理机制是","o":["毛细血管床大量关闭","毛细血管内流体静压降低","毛细血管壁通透性增高","动静脉吻合支开放","容量血管收缩"],"a":0,"e":"休克时交感神经兴奋，微动脉及毛细血管前括约肌强烈收缩，真毛细血管网大量关闭，组织灌注不足，故面色苍白、四肢湿冷、尿量减少。此时毛细血管流体静压降低而非升高。"},{"q":"某患儿，3岁，严重腹泻呈水样便，患儿呈深大呼吸，其最可能出现的酸碱平衡紊乱类型是","o":["代谢性酸中毒","代谢性碱中毒","呼吸性酸中毒","呼吸性碱中毒","混合型酸碱平衡紊乱"],"a":0,"e":"严重腹泻丢失大量碱性肠液，HCO3-减少致代谢性酸中毒，机体经深大呼吸排出CO2进行代偿。呼吸性酸中毒由通气障碍引起，与腹泻丢碱的机制相反。"},{"q":"一呼吸衰竭患者，其肺泡气PO2为102mmHg（13.6kPa），动脉血PO2为56mmHg（7.5kPa），该呼吸衰竭的可能病因是","o":["急性喉头水肿","呼吸肌麻痹","严重胸廓畸形","肺水肿","慢性阻塞性肺疾患"],"a":3,"e":"肺泡气氧分压接近正常而动脉血氧分压明显降低，提示肺泡与血液间弥散障碍；肺水肿时肺泡腔及间质积液增厚气血屏障，是常见原因。喉头水肿、呼吸肌麻痹及胸廓畸形则使肺泡通气不足。"},{"q":"患者，男，26岁。患有肛周脓肿，在肛周左侧破溃形成伤口，局部流脓不断，入院后检查，肛周伤口为外口，实与直肠相通，此病理管道为","o":["空洞","瘘管","窦道","溃疡","糜烂"],"a":1,"e":"脓肿破溃后形成一端开口于体表、另一端与直肠相通的病理性通道，连接内脏与体表，称瘘管。仅一端开口的盲管为窦道，坏死物经自然管道排出后残留的空腔为空洞。"},{"q":"患者，男。因呕吐、腹泻伴发热4天住院。患者自述虽口渴厉害但饮水即吐。查体：体温 38.6 ℃，呼吸、脉搏正常，血压110/80mmHg，有烦躁不安，口唇干裂。尿量约700ml/d。实验室检查：血清钠 155mmol/L ，尿钠 25mmol/L 。该患者出现的水、钠代谢紊乱类型是","o":["高渗性脱水","等渗性脱水","低渗性脱水","水中毒","水肿"],"a":0,"e":"血清钠155mmol/L高于正常，血浆渗透压升高，口渴明显、尿少、口唇干裂，符合高渗性脱水，因摄水不足而失水多于失钠。低渗性脱水血清钠低于130mmol/L。"},{"q":"患者，女， 21 岁。右颈单一无痛性淋巴结肿大，约2.2cm × 2.5cm ，活动欠佳。活检：淋巴结被膜完整，无明显的出血及坏死。镜下见淋巴结结构已破坏，大量束状纤维组织增生及一些散在的大细胞，其胞浆丰富、透明、核大、有多个嗜碱性核仁；细胞与周围组织之间形成透明的空隙。同时还可见嗜酸性粒细胞、浆细胞及少量的中性粒细胞。该病的最佳诊断为","o":["慢性非特异性淋巴结炎","结核性淋巴结炎","非霍奇金淋巴瘤","霍奇金淋巴瘤，混合细胞型","霍奇金淋巴瘤，结节硬化型"],"a":4,"e":"淋巴结结构破坏，胶原纤维束增生并分割成结节，散在腔隙型细胞伴嗜酸性粒细胞、浆细胞浸润，是结节硬化型霍奇金淋巴瘤的典型表现。混合细胞型缺乏纤维束与陷窝细胞。"},{"q":"某病人持续高热、心动过速、腹泻3周，后因中毒性休克死亡。尸体解剖发现死者弥漫性腹膜炎，回肠末端淋巴小结肿大、坏死和溃疡形成，并有穿孔，脾肿大，考虑最大可能性为","o":["细菌性痢疾","肠癌","急性肠炎","伤寒","结核"],"a":3,"e":"持续高热伴相对缓脉、腹泻，回肠末端淋巴小结坏死溃疡并穿孔，脾大，符合伤寒。伤寒沙门菌引起全身单核巨噬细胞系统增生，回肠下段集合淋巴小结病变最突出，溃疡期易穿孔。"},{"q":"患者，男，80岁。尸检中发现双侧肾脏对称性缩小，重量减轻，颜色苍白，质地变硬。肾包膜与肾实质粘连而难于剥离，肾表面呈弥漫性的细颗粒状。切面可见肾皮质萎缩变薄，皮髓质分界不清。光镜下，肾小球发生玻璃样变和硬化，其所属肾小管由于缺血而萎缩、消失。肾间质纤维组织增生，伴有淋巴细胞及浆细胞浸润。出现“肾小球集中”现象。肾内细、小动脉发生玻璃样变和内膜增厚。该患者生前最可能患有","o":["肾病综合征","急性肾炎综合征","慢性肾炎综合征","无症状血尿、蛋白尿","快速进行性肾炎综合征"],"a":2,"e":"双肾对称缩小、质硬、表面弥漫细颗粒状，镜下肾小球玻璃样变硬化、肾小管萎缩、间质纤维化并见肾小球集中，为慢性硬化性肾炎的表现，临床呈慢性肾炎综合征。"},{"q":"患者，男，21岁。1周前开始发热，午后高达40～41℃，伴腹痛、腹胀、便秘，无恶心、呕吐，不思饮食，全身乏力。右胸前皮肤有数个淡红色皮疹，压之褪色，肝肋下1、5cm，剑突下2cm，质软有轻度触痛，脾肋下2cm。该患者考虑诊断为","o":["急性肠炎","伤寒","急性肝炎","过敏性皮炎","败血症"],"a":1,"e":"持续高热、腹胀便秘、相对缓脉、玫瑰疹及肝脾大，为伤寒极期表现。伤寒沙门菌经消化道侵入回肠末段淋巴组织，引起单核巨噬细胞系统增生及菌血症。"},{"q":"48岁女性患者，病史2年，无自身免疫反应的表现，体型较胖，腹部B超未见异常回声，餐后2小时血糖8.5mmol/L，血胰岛素正常。该患者首先考虑可能患有","o":["非胰岛素依赖型糖尿病","胰岛素瘤","胃泌素瘤","胰多肽瘤","胰岛素依赖型糖尿病"],"a":0,"e":"中年肥胖、起病缓慢、病情较轻，血胰岛素水平正常且无酮症倾向，符合2型（非胰岛素依赖型）糖尿病。1型多见于青少年、胰岛素绝对缺乏；胰岛素瘤表现为反复低血糖。"},{"q":"一尸检的脑标本，肉眼见脑回变窄，脑沟加深变宽，脑室扩张。光镜下见神经细胞体积缩小，可见神经原纤维缠结。该标本的病理诊断为","o":["脑萎缩","脑坏死","脑梗死","脑软化","脑纤维化"],"a":0,"e":"脑回变窄、脑沟增宽、脑室扩张伴神经细胞体积缩小及神经原纤维缠结，为脑萎缩的形态学改变，见于阿尔茨海默病。脑梗死、脑软化以液化性坏死为主，不呈弥漫性脑回变窄。"},{"q":"一肝功能不全患者，两臂平举、手指分开、放松闭眼时，出现腕、掌指关节不规则、急速而微小的鸟翼样颤抖，最可能是发生了","o":["扑翼样震颤","帕金森综合征","特发性震颤","低血糖性震颤","甲亢性震颤"],"a":0,"e":"双上肢平举、手指分开时出现急促而不规则的腕部扑动，为扑翼样震颤，是肝性脑病的特征性体征。其发生与血氨等毒性物质蓄积、基底节受累有关。"},{"q":"一肝硬化患者，在饮食不当后出现上消化出血，遂往医院进行止血处理，三天后出现昏迷。该患者出现昏迷的原因最大可能是","o":["失血引起失血性休克","失血导致缺氧","血液蛋白在肠道内分解产生氨","出现严重感染","饮食不当导致体内毒素增多"],"a":2,"e":"上消化道出血后，血液蛋白在肠道被细菌分解产生大量氨，经门体分流进入体循环并透过血脑屏障，诱发肝性脑病而昏迷。失血致脑缺氧、感染亦为诱因，但以氨负荷骤增为主。"},{"q":"患者，男，20岁。近1个月来头痛、头晕伴恶性、呕吐，测血压为240/140mmHg，1年后，患者死亡。患者最可能的死亡原因是","o":["肾功能衰竭","眼底出血","脑水肿","左心衰竭","下肢坏疽"],"a":0,"e":"血压高达240/140mmHg属恶性高血压，进展迅速，细动脉纤维素样坏死及增生性动脉内膜炎致肾缺血，较早出现肾衰竭，为主要死因。脑出血与心力衰竭亦可致死。"},{"q":"患者，男，40岁。体检时发现直肠一息肉状肿物，肠镜活检示腺癌，肿瘤细胞未突破黏膜肌层。该患者应诊断为","o":["低级别上皮内瘤变","高级别上皮内瘤变","直肠黏膜内瘤变","直肠腺瘤","直肠腺癌"],"a":2,"e":"官方答案为【直肠黏膜内瘤变】，但依据教材，正确答案为【高级别上皮内瘤变】。WHO规定结直肠肿瘤只有侵破黏膜肌层到达黏膜下层才称为癌，未突破黏膜肌层的黏膜内癌归入高级别上皮内瘤变。"},{"q":"患儿因异物误入气管导致窒息而急诊入院，血气测定结果如下：pH：7.14，PaCO2：81mmHg，HCO3ˉ：26.5mmol/L，其酸碱平衡的代偿调节主要依靠","o":["血浆蛋白缓冲系统","碳酸氢盐缓冲系统","非碳酸氢盐缓冲系统","肺的调节","肾脏的调节"],"a":2,"e":"急性呼吸性酸中毒时CO2潴留，主要靠血红蛋白、磷酸盐等非碳酸氢盐缓冲系统及细胞内外离子交换缓冲，肾脏代偿需数日才建立。碳酸氢盐系统对挥发酸的缓冲能力有限。"},{"q":"患者，男，80岁。头痛数十年，以高热不退、畏寒、头痛10余天入院。实验室检查：外周血白细胞为：10.6×109/L，其中中性粒细胞占82%，CT检查发现左侧大脑有一个2cm×3cm大小坏死灶，经过抗炎治疗无效死亡。尸检病灶组织送病理检查，镜下发现：该病变组织液化坏死，有大量中性粒细胞浸润，伴有脓细胞，周围有成纤维细胞增生和新生的毛细血管形成。该病变属于","o":["蜂窝织炎","积脓","肉芽肿性炎","脓肿","炎性包裹"],"a":3,"e":"病灶组织液化坏死、大量中性粒细胞浸润并形成脓细胞，周围肉芽组织及新生毛细血管增生构成脓肿壁，为局限性化脓性炎。蜂窝织炎呈弥漫性化脓，不形成脓腔。"},{"q":"某烧伤面积达20%的女性患者，尿量240ml/24h，其最可能出现的电解质紊乱是","o":["高钠 血症","高钾血症","高钙血症","低钙血症","低磷血症"],"a":1,"e":"大面积烧伤后大量体液渗出致有效循环血量减少、肾血流下降、尿量减少，钾排出减少；组织坏死及红细胞破坏又释放钾，故出现高钾血症。低钙血症并非此期的主要紊乱。"},{"q":"患儿，女，13岁。1月前患扁桃体炎，经治疗痊愈。1周前开始发热，38℃，关节肿胀。检查发现，心率100次/分，心尖区闻及舒张期Ⅱ～Ⅲ级杂音。血白细胞升高，血沉加快。抗O滴度升高。该患者最可能发生的心脏疾病是","o":["病毒性心肌炎","细菌性心肌炎","免疫性心肌炎","风湿性心肌炎","寄生虫性心肌炎"],"a":3,"e":"链球菌感染后1～3周出现发热、游走性关节肿痛，抗O滴度升高、血沉加快并闻及心脏杂音，符合风湿性心肌炎。病毒性心肌炎无抗O升高，细菌性心肌炎为化脓性炎。"},{"q":"患者男，80岁。有30年高血压病史。近期心衰加剧，用β受体阻断剂可改善心衰症状。引起患者心衰加剧的信号转导异常机制主要可能是","o":["β1肾上腺素能受体上调","β1肾上腺素能受体下调","β1肾上腺素能受体产生自身抗体","β1肾上腺素能受体基因突变","β1肾上腺素能受体增敏"],"a":1,"e":"心力衰竭时交感神经长期兴奋使心肌β1受体下调、密度降低，心肌对儿茶酚胺反应性下降；β受体阻断剂可上调受体并逆转这一改变，故能改善症状。"},{"q":"患者，男，50岁。咯血伴左侧头痛、鼻塞、痰中带血6月。鼻咽部活检：非角化性癌。患者完善相关检查后行放射治疗。该治疗方案所依据的原则是","o":["抑制肿瘤细胞过度增殖","修复肿瘤细胞增殖缺陷","提高肿瘤细胞对药物的敏感性","诱导肿瘤细胞凋亡","减少组织细胞凋亡"],"a":3,"e":"放射线造成肿瘤细胞DNA双链断裂，损伤过重不能修复时经p53途径诱导凋亡，从而杀灭鼻咽癌细胞。该机制不是修复增殖缺陷或提高对药物的敏感性。"},{"q":"患者，女，45岁。阴道不规则流血半月，病理活检诊断子宫内膜腺体增生，该变化属于","o":["生理性增生","代偿性增生","内分泌性增生","不典型增生","肿瘤性增生"],"a":2,"e":"45岁女性雌激素绝对或相对增多，刺激子宫内膜腺体增生过长，引起不规则阴道流血，属内分泌性（激素性）增生。肿瘤性增生不受激素调节，呈单克隆性生长。"},{"q":"患者，女，47岁。右腿大隐静脉曲张12年，近日加重。遂行大隐静脉切除术。术中见静脉腔内有2个褐色物，与血管壁连接紧密，不易剥离。此褐色物质最可能是","o":["白色血栓形成","透明血栓形成","血栓形成并钙化","血栓形成并软化","血栓形成并机化"],"a":4,"e":"血栓形成后肉芽组织自血管壁长入并逐渐取代血栓，使其与管壁紧密粘连、不易剥离，即血栓机化，表面呈褐色。血栓软化后易脱落形成栓子，钙化则质硬如石。"},{"q":"Page-Frame患者，女，18岁。因高热，皮肤红疹4天入院，患者2周前右足大拇趾破损，未作任何治疗，入院前4天开始发热，体温39~40℃，且于发热第3天双下肢皮肤出现散在斑点状红疹，体温升高，持续不退，出现精神恍惚，谵语。查体：体温41℃，脉搏108次/分钟，肝肋下2指，脾于肋缘下可触及，右侧腹股沟淋巴结肿大，多个，质软。双下肢皮肤见散在、淡红色斑点，实验室检查：白细胞计数2.4×109/L，其中中性粒细胞占90%。血培养一周后结果显示金黄色葡萄球菌阳性。经抗菌素治疗、解热等综合治疗后体温渐退，3周缓解，4周出院。患者入院诊断应包括","o":["菌血症","毒血症","败血症","脓毒败血症","病毒血症"],"a":2,"e":"细菌自局部病灶入血并大量繁殖、产生毒素，引起高热、皮肤瘀点、脾及淋巴结肿大和白细胞显著升高，血培养阳性，为败血症。脓毒败血症另有多发性迁徙性脓肿。"},{"q":"男性，52岁，长期酗酒，近半年腹胀、食欲不振。体检时B超发现肝脏表面结节状，弥漫分布，腹腔里有积液，经肝穿刺活检镜下发现肝组织中有假小叶形成，病理诊断为：门脉性肝硬化。此时腹腔的积液主要是","o":["渗出液","漏出液","浆液","脓液","淋巴液"],"a":1,"e":"肝硬化门静脉高压使门静脉系统毛细血管流体静压升高，加之血浆胶体渗透压降低，腹水为淡黄色透明漏出液，蛋白低、细胞少、不自凝。渗出液见于炎症或肿瘤。"},{"q":"某患者血气分析结果为：pH 7.36，不可能的诊断为","o":["无酸碱平衡紊乱","代偿性酸中毒","代偿性碱中毒","混合性酸碱平衡紊乱","失代偿性酸碱平衡紊乱"],"a":4,"e":"pH7.36在正常范围内，故不存在失代偿性酸碱失衡。代偿性酸中毒、代偿性碱中毒及无酸碱紊乱时pH均可正常，混合型紊乱亦可相互抵消而使pH正常。"},{"q":"某患者高热数日，注射解热镇痛药后又大量出汗，最易发生的水钠代谢紊乱是","o":["低渗性脱水","等渗性脱水","高渗性脱水","水中毒","水肿"],"a":2,"e":"高热与解热镇痛药引起大量出汗，汗液为低渗液，失水多于失钠，加之饮水不足，血浆渗透压升高，发生高渗性脱水。等渗性脱水见于消化液大量丢失。"},{"q":"某缺氧患者，其呼吸加深加快的原因可能是","o":["CO中毒","亚硝酸盐中毒","进入通风不良的坑道","急性心力衰竭","KCN中毒"],"a":2,"e":"通风不良的坑道内氧分压降低，属低张性缺氧，经外周化学感受器反射性兴奋呼吸中枢，使呼吸加深加快。CO中毒、亚硝酸盐中毒及氰化物中毒时动脉血氧分压正常，不引起明显呼吸增强。"},{"q":"患者，女，28岁，有10年吸烟史。近3年来慢性咳嗽、咳白色泡沫痰，每年发病时间3个月以上。气管镜黏膜活检所见病变应是","o":["变质性炎","肉芽肿性炎","慢性非特异性炎症","化脓性炎","纤维素性炎"],"a":2,"e":"长期吸烟、每年咳嗽咳痰3个月以上且连续2年，支气管黏膜呈慢性非特异性炎症，表现为充血水肿、腺体增生肥大及淋巴细胞、浆细胞浸润。肉芽肿性炎见于结核等特异性感染。"},{"q":"男性，5岁，左腿烫伤后红肿、疼痛，数小时后起水疱。其病变为","o":["出血性炎","变质性炎","浆液性炎","蜂窝织炎","化脓性炎"],"a":2,"e":"Ⅱ度烧伤时浆液性渗出物积聚于表皮内及表皮下形成水疱，渗出液以血浆成分为主、蛋白含量低，属浆液性炎。化脓性炎渗出物含大量中性粒细胞，蜂窝织炎弥漫浸润疏松结缔组织。"},{"q":"患儿，男，7岁。3天前出现低热，咽痛，咳嗽和脓痰。当地医院就诊，查体：咽部充血，血常规提示白细胞为12×109/L，以中性粒细胞增高为主；皮肤可见瘀点，颈强直，克氏征阳性。病人首先考虑","o":["流行性脑脊髓膜炎","流行性乙型脑炎","急性支气管炎","大叶性肺炎","肺脓肿"],"a":0,"e":"儿童发热咽痛后出现皮肤瘀点、颈强直及克氏征阳性，提示脑膜刺激征伴败血症表现，符合脑膜炎双球菌引起的流行性脑脊髓膜炎。乙型脑炎以脑实质损害为主，无皮肤瘀点。"},{"q":"患者，女，25岁。患有风湿性二尖瓣狭窄合并主动脉瓣关闭不全。乏力、纳差，伴发热20天。查体：体温37.8℃，血红蛋白80g/L，白细胞计数9.2×109/L，皮肤有瘀点，脾大，心尖部可闻及舒张期杂音，主动脉瓣区可闻及舒张期杂音。该患者最符合的疾病是","o":["风湿性心肌炎","贫血性心脏病","风心病，心力衰竭","先天性主动脉瓣病变","风湿性瓣膜病合并感染性心内膜炎"],"a":4,"e":"原有风湿性二尖瓣与主动脉瓣病变，近期发热、贫血、皮肤瘀点及脾大，为风湿性瓣膜病合并感染性心内膜炎，赘生物形成、栓塞及免疫反应引起上述全身表现。"},{"q":"某田径运动员参加奥运会百米赛跑，当他听到起跑信号时，体内最明显升高的激素是","o":["儿茶酚胺","β-内啡肽","糖皮质激素","胰岛素","醛固酮"],"a":0,"e":"起跑信号经交感神经使肾上腺髓质释放肾上腺素与去甲肾上腺素，血中儿茶酚胺迅速升高，心率加快、血压升高、肌糖原分解供能。糖皮质激素起效慢，胰岛素分泌减少。"},{"q":"患者，男，66岁。慢性咳嗽、咳痰18年，每年冬季加重。近来咳嗽，咳白色黏痰，呼吸困难加重。体查发现患者呈桶状胸，肋间隙增宽，双肺可闻及小水泡音，最可能的诊断是","o":["慢性支气管炎，肺气肿","大叶性肺炎，肺气肿","肺癌，小叶性肺炎","肺结核，小叶性肺炎","慢性支气管炎，支气管扩张"],"a":0,"e":"慢性咳嗽咳痰18年、冬季加重，逐渐出现呼气性呼吸困难及桶状胸、肋间隙增宽，为慢性支气管炎并发阻塞性肺气肿。大叶性肺炎起病急、有实变体征，与本例慢性过程不符。"},{"q":"患者，男，20岁。稽留高热3周，伴腹胀、腹泻入院，当晚突然出现腹痛，体温骤降至35、5℃，脉搏120次/分，血压60/45mmHg，腹部压痛、反跳痛明显，肝浊音界缩小。实验室检查：WBC：18.0×109/L，N：0.88，L：0.12，肥达反应H：1:320, O：1:320，最可能的诊断是","o":["胃溃疡穿孔","阑尾炎穿孔","肠伤寒穿孔","胆囊炎胆囊穿孔","阿米巴痢疾肠穿孔"],"a":2,"e":"稽留高热、腹胀腹泻，突发腹痛伴腹膜刺激征、肝浊音界缩小及血压下降，肥达反应O、H均1:320，符合伤寒回肠淋巴小结坏死溃疡穿孔。阿米巴痢疾以果酱样便为特征。"},{"q":"某患者上呼吸道感染伴发热 2 天，出现浑身肌肉酸痛的原因是","o":["糖原分解加强","脂肪分解加强","蛋白质分解加强","维生素消耗增多","皮肤、呼吸道水分蒸发增多"],"a":0,"e":"发热时代谢率增高，交感神经兴奋使肝糖原分解加强、血糖升高，肌肉无氧酵解增强致乳酸堆积，故全身肌肉酸痛。脂肪与蛋白质分解亦增强，但非酸痛的主要原因。"},{"q":"患者，女，45岁。同房接触性出血一周。检查子宫颈有一菜花状肿物，触之易出血。镜下见异型细胞呈巢状结构，有角化珠形成，浸润宫颈间质。该患者应诊断为","o":["慢性宫颈炎","宫颈原位癌","宫颈鳞癌","宫颈尖锐湿疣","宫颈炎性息肉"],"a":2,"e":"宫颈菜花状肿物、触之易出血，镜下癌细胞呈巢状并有角化珠形成、浸润间质，为宫颈鳞状细胞癌。原位癌未突破基膜，尖锐湿疣见挖空细胞而无角化珠及浸润。"},{"q":"患者，女，50岁。近三年来，活动后出现胸痛，常放射至左肩，左臂内侧，每次发作含硝酸甘油后缓解。诊断为冠状动脉粥样硬化。下列哪些习惯对病情无益","o":["低脂饮食","控制血压","不吸烟","不饮酒","大量运动"],"a":4,"e":"冠心病患者应低脂饮食、控制血压、戒烟限酒；剧烈大量运动使心肌耗氧量骤增，可诱发心绞痛甚至心肌梗死，故对病情无益，运动应适量。"},{"q":"患儿，3月女婴，因呕吐、腹泻伴发热 2 天入院。体检：体重 7.8kg ，体温 38.9 ℃。神志清楚，烦躁不安，面色发红，前囱及眼窝轻度凹陷，口唇黏膜干裂，常作口渴欲饮状。皮肤明显干燥，弹性较差。实验室检查：K+：4.6mmol/L ， Na+：158mmol/L 。该患儿最有可能的诊断是","o":["水中毒","等渗性脱水","低渗性脱水","高渗性脱水","水肿"],"a":3,"e":"患儿腹泻呕吐失水，血清钠158mmol/L、血浆渗透压升高，伴烦躁、口渴、前囟及眼窝凹陷、皮肤干燥，符合高渗性脱水。等渗性脱水血钠正常，低渗性脱水血钠降低。"},{"q":"一患者由于慢性呼吸衰竭，检测动脉血PaCO2为85mmHg，出现头痛，烦躁，言语不清等“CO2麻醉”效应，其发生机制不包括","o":["颅内压降低","脑血流量增加","脑细胞内Na+、水增多","脑毛细血管通透性增高","氢离子浓度升高"],"a":0,"e":"CO2潴留使脑血管扩张、脑血流量增加，脑毛细血管通透性增高，血浆及Na+、水进入脑细胞形成脑水肿，颅内压升高而非降低，出现头痛、烦躁乃至昏迷，即CO2麻醉。"},{"q":"一名儿童出现发热，并伴有咳嗽，胸透见两肺下叶散在边缘不清的小点状阴影，最有可能的诊断是","o":["干酪样肺炎","小叶性肺炎","大叶性肺炎","间质性肺炎","转移性肿瘤"],"a":1,"e":"儿童发热咳嗽，双肺下叶散在边缘不清的小点状阴影，为以细支气管为中心的化脓性炎，即小叶性肺炎。大叶性肺炎呈大叶分布的实变影，干酪样肺炎见于干酪性结核。"},{"q":"患者，男，69岁。患高血压病13年。因劳累后突发呼吸困难，咳粉红色泡沫痰就诊。血压190/100mmHg，对该患者的最佳治疗措施是","o":["扩张动脉血管，降低心脏的后负荷","增强心肌收缩力","使用支气管扩张剂","扩张静脉血管，降低心的前负荷","高流量吸氧"],"a":0,"e":"血压190/100mmHg、咳粉红色泡沫痰提示高血压所致急性左心衰竭，后负荷过重为主要矛盾，扩张动脉降低后负荷可减少心肌耗氧、增加心排出量。增强心肌收缩力并非首要措施。"},{"q":"患者，女，40岁。查体时发现右肺靠近胸膜处有一直径4cm的肿物，与周围肺组织分界不清，同时右肺门及右锁骨上淋巴结肿大，该女士可能患有","o":["肺癌","肺结核","肺脓肿","肺炎性假瘤","大叶性肺炎"],"a":0,"e":"近胸膜处边界不清的4cm肿块伴同侧肺门及锁骨上淋巴结肿大，符合周围型肺癌伴淋巴道转移。结核球多边界清楚并有钙化，炎性假瘤为良性病变、无淋巴结转移。"},{"q":"患者，男，80岁。因心肺功能衰竭而长期卧床。死亡后尸检见肺组织散在多发小实变区。制片后镜下观察，见细支气管上皮细胞坏死脱落，管腔内及周围有大量炎性渗出物，以中性粒细胞为主。该患者肺部病变提示死前可能患有","o":["大叶性肺炎","小叶性肺炎","病毒性肺炎","慢性支气管炎","肺结核"],"a":1,"e":"久病卧床、心肺功能衰竭者，出现以细支气管为中心的化脓性炎，病灶散在多发，为小叶性肺炎（坠积性肺炎）。大叶性肺炎累及整个肺大叶，病毒性肺炎为间质性炎。"},{"q":"一个恶性肿瘤患者在X线检查时发现肺内有多个散在的圆形阴影，首先考虑恶性肿瘤发生了","o":["支气管播散","淋巴道转移","种植性转移","不典型增生","血道转移"],"a":4,"e":"恶性肿瘤细胞侵入血管随血流运行，在肺内形成多个散在、大小相近的圆形转移结节，为血道转移的典型表现。淋巴道转移表现为肺门及纵隔淋巴结肿大。"},{"q":"患者，女，28岁。劳累后心悸、气促4年，近来加重，夜间不能平卧就诊。查体：心率110次/分，心音强弱不等，心尖部可闻及舒张期隆隆样杂音，肺底可闻及细小水泡音。心脏彩超显示二尖瓣狭窄。该患者夜间不能平卧的主要原因是","o":["入睡后迷走神经兴奋性增高，呼吸道阻力增大","平卧时回心血量增多，加重心的前负荷","神经反射敏感性增高","膈肌位置相对下移","需氧量增加"],"a":1,"e":"夜间平卧时下肢及腹腔血液回流增多，回心血量增加，二尖瓣狭窄使左心房压进一步升高，肺淤血加重而致呼吸困难，故需高枕卧位。迷走神经兴奋性增高并非主要原因。"},{"q":"患者，男，38岁。外伤大出血而急诊入院。患者面色苍白，四肢湿冷，烦躁不安，心率90次/分，血压95/80mmHg。此时患者体内可维持正常血液供应的器官是","o":["皮肤、肝","心、脑","肝、肾","肺、肝","脾、肾"],"a":1,"e":"休克早期交感神经兴奋使皮肤、内脏及肾血管强烈收缩，血液重分布以保证心、脑灌注，故心脑功能基本维持，而皮肤苍白湿冷、尿量减少。肝、肾、脾血流明显减少。"},{"q":"患者，女，23岁。结核性腹膜炎伴有肠梗阻入院手术。手术后禁食，并连续做胃肠减压7天，共抽吸液体2200ml，平均每天静脉补液(5%葡萄糖液)2500ml。术后2周，患者出现肌肉软弱无力，肢体瘫软，不能翻身，偶尔有麻木感。恶心，呕吐，厌食，腹胀，全身乏力等症状。实验室检查：血清钾2.4 mmol/L,血清钠140 mmol/L。心电图显示：ST段压低，T波低平和增宽，有U波。患者发生的水、电解质代谢紊乱类型为","o":["高钠血症","低钠血症","低钾血症","高钾血症","水中毒"],"a":2,"e":"连续胃肠减压抽吸大量消化液，术后仅补葡萄糖液，钾摄入不足而排出增多，血清钾2.4mmol/L，出现肌无力、腹胀、心律失常及ST段压低、T波低平、U波，为低钾血症。"},{"q":"患者，男，60岁。近期出现乏力、厌食、肝区疼痛加重。肝活检显示，肝细胞出现脂肪变性、碎片样坏死，肝组织有炎症细胞浸润。患者10年前查出HCV（+）。患者现在最可能的诊断是","o":["慢性乙型病毒性肝炎","慢性丙型病毒性肝炎","乙型病毒性肝炎","丙型病毒性肝炎","酒精性肝炎"],"a":1,"e":"HCV感染十年，肝细胞脂肪变性、碎片状坏死伴炎症细胞浸润，为慢性丙型肝炎。丙型肝炎病毒感染后易慢性化，肝细胞脂肪变性是其较特征性的改变。"},{"q":"患者，男，25岁。因急性黄疸性肝炎入院。在治疗过程中出现呕吐咖啡色物及黑便，体检发现腹部及剑突下皮肤瘀斑，转氨酶明显增高，出、凝血时间延长，3P试验阳性，外周血涂片发现多量裂体细胞。此时该患者最恰当的诊断是","o":["肝功能衰竭","上消化道大出血","溶血性贫血","DIC","肾功能衰竭"],"a":3,"e":"重症肝炎时凝血因子合成障碍，组织因子大量释放激活凝血系统，出现皮肤瘀斑、穿刺部位出血、3P试验阳性及裂体细胞，符合DIC，3P阳性提示继发性纤溶亢进。"},{"q":"患者，女，31岁。主诉：经常感冒，主要症状是：咳嗽、咳痰，并时有鼻塞、流鼻涕甚至头痛等症状。由于晚上鼻塞，常常难以入睡，尤其季节交替时更为严重。痰液送病理检查发现有大量的嗜酸性粒细胞。该病人初步诊断为","o":["感冒","病毒感染","细菌感染","过敏性鼻炎","无法判断"],"a":3,"e":"鼻塞流涕呈季节性发作，痰中见大量嗜酸性粒细胞，提示Ⅰ型超敏反应，为过敏性鼻炎。细菌感染以中性粒细胞为主，病毒感染以淋巴细胞为主。"},{"q":"患者，女，25岁。近3个月来反复出现发热，大关节出现游走性疼痛，伴有红、肿，乏力，不爱活动，稍活动后即有心跳加快。入院检查，肘、腕、膝关节附近伸侧皮下可触及圆形、质硬、无压痛结节。皮下结节内可见到的成分不含有","o":["纤维素样坏死","淋巴细胞","成纤维细胞","Aschoff细胞","中性粒细胞"],"a":4,"e":"风湿性皮下结节为增生性病变，中央为纤维素样坏死，周围有淋巴细胞、成纤维细胞及Aschoff细胞，不含中性粒细胞。中性粒细胞浸润见于渗出性炎及感染性心内膜炎赘生物。"},{"q":"患者，男，40岁。在私人诊所洗牙后出现肝功能异常，AST和ALT显著升高。实验室检查，乙肝表面抗原（+）。病人可能的诊断是","o":["甲型病毒性肝炎","乙型病毒性肝炎","丙型病毒性肝炎","丁型病毒性肝炎","戊型病毒性肝炎"],"a":1,"e":"洗牙属有创操作，可经血液传播乙肝；患者HBsAg阳性、转氨酶显著升高，为乙型病毒性肝炎。甲型、戊型肝炎经粪-口传播，与本例暴露方式不符。"},{"q":"患者，女，45岁，交通意外导致全身软组织挤压伤，面色苍白，四肢湿冷，神志清醒，血压90/70mmHg，此时判断患者肾功能障碍的主要依据是","o":["少尿","多尿","肾性贫血","肾性高血压","氮质血症"],"a":0,"e":"挤压伤后休克，肾血流量减少致肾小球滤过率下降，24小时尿量少于400ml即少尿，是判断急性肾功能障碍最早期、最主要的依据。氮质血症与肾性贫血出现较晚。"},{"q":"患者，男，50岁。肺气肿病史6年，1小时前劳作后突然呼吸困难加重，右侧胸痛，大汗，发绀，应首先考虑的诊断是","o":["干性胸膜炎","急性心肌梗死","自发性气胸","细菌性肺炎","急性肺栓塞"],"a":2,"e":"肺气肿患者肺大疱破裂，突发胸痛、呼吸困难加重及发绀，为自发性气胸，患侧呼吸音减弱、叩诊鼓音。急性心肌梗死多有胸骨后压榨痛及心电图改变。"},{"q":"患者，男，52岁，三年前诊断为下肢脉管炎，近二个月来出现左下肢第一足趾逐渐变黑、变硬、干燥、疼痛，此足趾最为可能的病变是","o":["出血性梗死","黑色素瘤","干性坏疽","湿性坏疽","气性坏疽"],"a":2,"e":"血栓闭塞性脉管炎致下肢动脉闭塞、侧支循环不足，足趾缺血坏死，因水分蒸发而干燥皱缩、呈黑色，与周围组织界限清楚，为干性坏疽。湿性坏疽伴腐败菌感染，肿胀恶臭。"},{"q":"患者，男，17岁。身体瘦弱。近日咳嗽乏力，晚间睡觉常出虚汗，胸部X光片检查发现右肺上叶锁骨上下有絮状阴影，首先应考虑的诊断是","o":["大叶性肺炎","间质性肺炎","周围型肺癌","浸润型肺结核","局灶型肺结核"],"a":3,"e":"青少年出现乏力盗汗，X线示右肺上叶锁骨上下边缘模糊的云絮状阴影，为浸润型肺结核，是最常见的活动性继发性肺结核。局灶型肺结核病灶局限、多无自觉症状。"},{"q":"患者，女，50岁。双上肢剧烈颤抖，双手甚，走路出现剪刀步，全身僵硬，易摔倒，同时不停震颤导致肌肉酸痛，不能坐，无法进食。此病人可能患有","o":["胶质瘤","脑膜瘤","海绵状脑病","阿尔茨海默病","帕金森病"],"a":4,"e":"静止性震颤、肌强直、运动迟缓及姿势步态异常（剪刀步、易跌倒），为帕金森病，由黑质多巴胺能神经元变性及路易小体形成所致。阿尔茨海默病以进行性痴呆为主。"},{"q":"患者，男，46岁。因消化性溃疡突然呕血而致失血性休克，面色苍白，四肢湿冷，神志清醒，血压110/96mmHg，此时患者可能处于","o":["休克早期","休克期","休克晚期","失代偿期","DIC"],"a":0,"e":"失血后出现面色苍白、四肢湿冷、烦躁不安，血压尚在正常范围，为休克早期即微循环痉挛期，机体尚处代偿阶段。休克期血压明显下降，晚期出现DIC及多器官衰竭。"},{"q":"患者，男，35岁。近期出现乏力、厌食、肝区疼痛。据调查，患者有长期和乙型肝炎患者密切接触史。患者应首先检查","o":["肝穿刺活检","肝炎病毒标记物","腹部B超","胃肠钡餐造影","CT"],"a":1,"e":"有乙型肝炎密切接触史并出现乏力、厌食、肝区痛，应首先检测乙肝病毒标志物以明确病因。肝穿刺活检有创，影像学检查不能确定病原。"},{"q":"患者，男，40岁。因肝右叶肝癌而行肝叶切除术，患者的肝脏最有可能发生的病理变化是","o":["经过较长时间，恢复肝脏原结构","保持手术后剩余肝脏的状态","肝脏肝小叶不断增生","肝脏形成若干再生结节","肝脏纤维组织大量增生"],"a":0,"e":"肝脏再生能力很强，肝叶切除后残存肝细胞通过代偿性增生，经较长时间可恢复原有小叶结构，不形成再生结节。再生结节见于肝硬化时肝细胞反复坏死与增生的背景。"},{"q":"患者，男，55岁。自述肝区疼痛，同时伴有食欲不振，消化不良。B超显示，肝脏体积缩小，脾脏肿大。患者无病毒性肝炎、酗酒等病史，实验室检查发现感染华支睾吸虫。该患者可能的诊断是","o":["门脉性肝硬化","坏死后性肝硬化","寄生虫性肝硬化","淤血性肝硬化","胆汁性肝硬化"],"a":2,"e":"华支睾吸虫寄生于胆管，虫体及其代谢产物长期刺激引起胆管周围纤维组织增生，最终形成寄生虫性肝硬化。患者无肝炎及酗酒史，可排除病毒性与酒精性肝硬化。"},{"q":"某患者呼吸骤停，血气分析结果如下：pH：7.19，PaCO2： 70mmHg， HCO3-：26mmol/L，可诊断为","o":["代谢性碱中毒","急性呼吸性酸中毒","慢性呼吸性酸中毒","代谢性酸中毒","呼吸性酸中毒合并代谢性碱中毒"],"a":1,"e":"呼吸骤停致肺泡通气严重不足，CO2潴留使PaCO2升至70mmHg，pH降至7.19而HCO3-尚属正常，符合急性呼吸性酸中毒，肾脏代偿尚未建立。"},{"q":"患者，男，45岁。精神混乱、多尿、烦渴、便秘加重2天，急诊入院。5年前因烧伤右手臂患慢性骨髓炎。体格检查深部肌腱反射减弱。在检查过程中，患者也表现出明显的不适和无方向感，并且不配合。EKG显示QT间期缩短。实验室指标如下：血钙5、94mmol/L，血清白蛋白1.45mmol//L，BUN：1.4mg/dl，PTH：12pg/dl，碱性磷酸酶980U/L，该患者可能出现的电解质紊乱是","o":["高钙血症","低钙血症","低钾血症","高钾血症","高镁血症"],"a":0,"e":"血钙显著升高，伴QT间期缩短、多尿烦渴、便秘及精神症状，符合高钙血症；慢性骨髓炎长期制动使骨钙动员增加。低钙血症表现为QT延长及手足搐搦。"},{"q":"患者，男，45岁。有长期“胃痛”史。曾诊断胃溃疡病。此次病理活检诊断为腺癌。镜下诊断的主要依据应是","o":["腺上皮异常增生","呈浸润性生长，有角化珠形成","癌细胞呈腺管样结构","癌细胞异型性明显，核分裂多见","癌细胞染色深、核仁明显"],"a":2,"e":"胃腺癌镜下诊断的关键是癌细胞形成不规则的腺管样结构并浸润黏膜下层。角化珠见于鳞癌，细胞异型性明显、核分裂多仅提示恶性，不能确定腺上皮来源。"},{"q":"一患者因血压升高、水肿严重1周就诊，10年前曾确诊为慢性肾小球肾炎，实验室检查发现内生肌酐清除率为22ml/min，尿比重固定在1.008~1.012。该患者最可能的诊断是","o":["少尿型ARF","非少尿型ARF","CRF肾功能不全期","CRF肾衰竭期","尿毒症"],"a":3,"e":"有慢性肾炎史，内生肌酐清除率降至22ml/min，尿比重固定于1.008～1.012提示肾浓缩功能丧失，伴严重水肿及高血压，属慢性肾衰竭肾衰竭期。尿毒症期常有明显自体中毒症状。"},{"q":"患者，男，80岁。近一年来，出现严重记忆力下降，经常喊错家人的名字，出门找不到家，CT显示大脑出现普遍性萎缩。上述表现提示此人患有","o":["胶质瘤","脑膜瘤","海绵状脑病","阿尔茨海默病","帕金森病"],"a":3,"e":"老年起病，进行性记忆力减退、认错家人、外出迷路，CT示大脑普遍性萎缩，为阿尔茨海默病的典型表现。帕金森病以震颤、肌强直等运动障碍为主。"},{"q":"患者，女，25岁。面部蝶形红斑，反复出现发热及关节肿痛，病程迁延反复。肾活检可见，肾小球内大量内皮下免疫复合物沉积，并出现苏木素小体。该患者的肾脏病变符合","o":["系膜增生性肾小球肾炎","局灶性肾小球肾炎","膜性肾小球肾炎","弥漫增生型狼疮性肾炎","快速进行性肾小球肾炎"],"a":3,"e":"面部蝶形红斑、发热、关节痛，肾活检见内皮下大量免疫复合物沉积及苏木素小体，为弥漫增生型狼疮性肾炎，是系统性红斑狼疮急性期的特征性病变。"},{"q":"消化道溃疡患者服用过多碳酸氢钠，导致酸碱失衡，血气分析结果表现为pH：7.50，PaCO2：48mmHg，HCO3ˉ：36mmol/L，可判断为","o":["代偿性代谢性碱中毒","代偿性呼吸性碱中毒","失代偿性代谢性碱中毒","失代偿性呼吸性碱中毒","代谢性碱中毒合并呼吸性酸中毒"],"a":2,"e":"大量服用碳酸氢钠致碱中毒，HCO3-升至36mmol/L，pH7.50超出正常上限，PaCO2虽代偿性升高但未使pH回至正常，故为失代偿性代谢性碱中毒。"},{"q":"患者，男，65岁。糖尿病患者，自己使用胰岛素治疗，结果出现四肢肌肉无力、腹胀、心律失常等表现。该患者最可能的诊断为","o":["低钠血症","低钙血症","高钠血症","高钾血症","低钾血症"],"a":4,"e":"胰岛素过量使葡萄糖转入细胞内，钾随之进入细胞，加之摄入不足，血钾降低，出现肌无力、腹胀及心律失常。高钾血症多表现为心率缓慢、心脏停搏。"},{"q":"患者，女，25岁，3 天前开始出现咽痛、咳嗽等症状，体温38.0℃，无其他明显不适症状。请问下列哪项处理原则不恰当","o":["尽快找出原发病并进行治疗","立刻给予药物解热","注意补充营养物质和水","注意休息避免劳累","必要时可给予物理降温"],"a":1,"e":"体温38℃属低中度发热，发热是机体防御反应，不应立即用解热药强行降温以免掩盖病情，应查明病因、注意休息补液，必要时物理降温。"},{"q":"某慢性肾衰竭患者，病久逐渐出现肾性佝偻病，其发病机制主要是","o":["水钠代谢失调","钾代谢失调","钙磷代谢失调","镁代谢失调","氮质血症"],"a":2,"e":"慢性肾衰竭时肾小球滤磷减少致血磷升高、血钙降低，活性维生素D3合成不足使肠钙吸收减少，骨钙化障碍，儿童表现为肾性佝偻病，核心环节是钙磷代谢失调。"},{"q":"某幽门梗阻患者发生反复呕吐，血气分析结果为pH：7.5，最可能的酸碱平衡紊乱类型是","o":["代谢性酸中毒","代谢性碱中毒","呼吸性酸中毒","呼吸性碱中毒","混合型酸碱平衡紊乱"],"a":1,"e":"幽门梗阻反复呕吐大量胃液，丢失H+和Cl-，肠内HCO3-不能被中和而相对增多，pH7.5提示代谢性碱中毒。胃酸大量丢失是其发生的关键。"},{"q":"患者，男，60岁。患高血压数年。近1个月来头痛、头晕伴恶性、呕吐，测血压为180/100mmHg，清晨起床时家属发现患者死亡，患者死前小便失禁。患者最可能的死亡原因是","o":["肾功能衰竭","眼底出血","脑出血","右心衰竭","下肢坏疽"],"a":2,"e":"高血压患者夜间猝死、死前尿失禁，提示脑出血。长期高血压使脑内小动脉形成微小动脉瘤，血压骤升时破裂，出血量大者迅速昏迷并因脑疝致死。"},{"q":"一肝功能不全患者，突然出现嗜睡，唤之可醒，伴明显精神错乱，见扑翼样震颤，提示该患者处于肝性脑病的哪一期","o":["前驱期","昏迷前期","昏睡期","昏迷期","震颤期"],"a":2,"e":"嗜睡但可唤醒，醒时精神错乱，伴扑翼样震颤，属肝性脑病第三期即昏睡期。前驱期仅性格行为改变，昏迷前期以意识错乱、睡眠倒错为主，昏迷期不能唤醒。"},{"q":"某患者血气检查的结果：血氧容量20ml/dl（正常值为20ml/dl），动脉血氧含量19ml/dl(正常值为19ml/dl)，动脉血氧分压100mmHg(正常值为100mmHg)，动-静脉血氧含量差6ml/dl(正常值为5ml/dl)。请判断该患者的缺氧类型","o":["低张性缺氧","循环性缺氧","血液性缺氧","乏氧性缺氧","组织性缺氧"],"a":1,"e":"动脉血氧分压、血氧容量及动脉血氧含量均正常，而静脉血氧分压升高、动静脉氧含量差减小，提示组织摄取氧减少，属循环性缺氧。组织性缺氧由细胞利用氧障碍所致。"},{"q":"患者，男，40岁。背部红、肿、热、痛7天，表面有3个溃破口，流黄色凝乳状液体，按之深部有波动感。其病变最可能的病因是","o":["溶血性链球菌感染","大肠杆菌感染","金黄色葡萄球菌感染","绿脓杆菌感染","变形杆菌感染"],"a":2,"e":"背部红肿热痛、多个溃破口并流出黄色脓液、深部有波动感，为痈，多由金黄色葡萄球菌引起；该菌产生血浆凝固酶使病变局限并易形成脓肿。溶血性链球菌多致弥漫性蜂窝织炎。"},{"q":"某患者肺泡-动脉氧分压差为60mmHg,吸纯氧30分钟后无改善，最可能发生的情况是","o":["解剖分流增加","功能分流增加","弥散障碍","肺泡扩张受限","气道阻塞"],"a":0,"e":"肺泡-动脉氧分压差增大，吸纯氧30分钟后低氧血症不改善，提示存在解剖分流（真性分流），该部分血液完全未接触通气肺泡。功能分流及弥散障碍吸氧后可明显改善。"},{"q":"某运动员在训练时发生股骨骨折，因处理不当，大量脂肪滴进入血液。该运动员出现呼吸困难，咳嗽、咳粉红色泡沫状痰。推测该运动员体内脂肪栓子可能栓塞于","o":["左心房","左心室","肺静脉及其分支","肺动脉及其分支","主动脉分支"],"a":3,"e":"骨折后脂肪滴进入静脉，随血流经右心进入肺动脉及其分支引起肺脂肪栓塞，出现呼吸困难、发绀，重者咳粉红色泡沫痰。小的脂肪栓子可经肺毛细血管入左心引起体循环栓塞。"},{"q":"女性，65岁，经确诊为慢性支气管炎，肺气肿12年，此次感冒后再次发作，呼吸困难加重且伴有口唇发绀入院，未经吸氧，下列的血气指标结果与之相符的是","o":["PaO2降低，PaCO2升高","PaO2正常，PaCO2升高","PaO2降低，PaCO2正常","PaO2正常，PaCO2降低","PaO2降低，PaCO2降低"],"a":0,"e":"慢性支气管炎、肺气肿患者气道阻塞致通气不足，肺泡氧分压下降而CO2潴留，血气表现为PaO2降低、PaCO2升高，属Ⅱ型呼吸衰竭，与口唇发绀相符。"},{"q":"患者右小腿皮肤破溃不愈合半年就诊，见破溃处为火山口状溃疡，边缘较硬灰白色，伴明显出血、坏死。此病变最可能的诊断是","o":["皮肤鳞癌","皮肤慢性炎症","皮肤扁平苔藓","皮肤老年疣","皮肤良性溃疡"],"a":0,"e":"溃疡呈火山口状、边缘隆起质硬、底部坏死出血明显，为恶性溃疡的表现，结合部位应考虑皮肤鳞状细胞癌。良性溃疡边缘整齐、底部平坦，炎症性溃疡无明显坏死。"},{"q":"一患者因充血性心力衰竭和心律失常入院，主诉近期胃口差，伴恶心、呕吐、腹泻，记忆力减退，夜不成寐，家人诉说其“口臭”严重，检查发现其皮肤色素颜色较深，表面附有白色结晶。其最可能的诊断是","o":["CRF肾功能不全期","CRF肾衰竭期","尿毒症","少尿型ARF","非少尿型ARF"],"a":2,"e":"慢性肾衰晚期大量尿素随汗液排出，在皮肤表面形成白色结晶即尿素霜，伴氨味口臭、色素沉着及胃肠道、神经症状，符合尿毒症。肾衰竭期尚无如此广泛的自体中毒表现。"},{"q":"患者，男，69岁。恶性肿瘤晚期出现全身严重消耗状态，体重减轻。其全身性萎缩发生的原因最主要是","o":["压迫性萎缩","失用性萎缩","去神经性萎缩","内分泌性萎缩","营养不良性萎缩"],"a":4,"e":"恶性肿瘤晚期长期消耗、蛋白质摄入不足而分解增加，导致全身肌肉萎缩、体重明显下降，即恶病质，属营养不良性萎缩。压迫性、失用性萎缩均为局部改变。"},{"q":"患者，男，63岁。吸烟，反复咳嗽，咳白色泡沫痰20余年，气促10年，近两天因受寒后出现发热伴咳黄脓痰，气喘不能平卧，查体双肺语颤减弱，可闻及散在干湿性啰音，心界缩小，心率110次/分，该患者最可能的诊断是","o":["慢性支气管炎急性发作","支气管哮喘","支气管扩张","肺结核","肺癌"],"a":0,"e":"老年吸烟者长期咳嗽咳白痰，受寒后发热、黄脓痰、气喘，双肺闻及干湿啰音，为慢性支气管炎急性发作。支气管哮喘以发作性呼气性呼吸困难及哮鸣音为主，无长期咳痰史。"},{"q":"患者，女，35岁，两下肢严重挤压伤，面色苍白，四肢湿冷，血压90/70mmHg。经初步抗休克处理后，患者出现进行性呼吸困难和缺氧，吸氧不能改善，患者最可能出现了","o":["输液过多","吸入性肺炎","心功能不全","急性呼吸窘迫综合征","呼吸道阻塞"],"a":3,"e":"严重挤压伤后经抗休克治疗出现进行性呼吸困难及吸氧不能纠正的低氧血症，为急性呼吸窘迫综合征，由肺毛细血管内皮与肺泡上皮损伤、透明膜形成所致。"},{"q":"某冠心病病人，于剧烈运动后出现心绞痛症状，服用硝酸甘油不能缓解，遂拨打120求救。救护车于80分钟后将病人送到医院。医院为防治再灌注损伤采取的治疗措施中不包括","o":["低压、低流、低温灌注","高pH、高钙、高钠灌注","再灌注前给予SOD和CAT","给予牛磺酸","使用非甾体类抗炎药"],"a":4,"e":"再灌注损伤的防治包括低压低流低温灌注、再灌注前给予SOD和过氧化氢酶清除氧自由基、补充牛磺酸等；非甾体抗炎药抑制前列腺素合成，对再灌注损伤无防治作用。"},{"q":"在一肺组织切片中，可见多数细支气管壁充血水肿，并有大量中性粒细胞浸润，管腔内也有大量中性粒细胞。周围肺泡内有大量浆液脓性渗出物，此时最可能的诊断是","o":["大叶性肺炎","小叶性肺炎","支原体肺炎","病毒性肺炎","肺结核"],"a":1,"e":"病变以细支气管为中心，管壁充血水肿并有大量中性粒细胞浸润，周围肺泡充满浆液脓性渗出物，为小叶性肺炎。大叶性肺炎为弥漫性纤维蛋白性炎，肺泡壁结构完整。"},{"q":"患者，女，58岁。咳嗽、咳痰8年，吸烟史20年，桶状胸，双肺可听到少量湿罗音，肝脾不大，最可能的诊断是","o":["大叶性肺炎","肺气肿","胸腔积液","支气管哮喘","肺癌"],"a":1,"e":"长期咳嗽咳痰、吸烟，出现桶状胸及双肺湿啰音，为慢性支气管炎并发肺气肿，肺组织过度充气、弹性回缩力下降。大叶性肺炎有实变体征且起病急。"},{"q":"患者，男，55岁。出现严重的血尿和右腰部疼痛。体检发现腹部肿块。全血细胞计数（CBC）显示血红蛋白水平为21g/dL和红细胞增多。超声波显示右侧肾脏上极有一个6、0cm的肿块。患者红细胞增多症最可能的解释是","o":["肝细胞癌","卵巢癌","肾上腺皮质腺瘤","肾癌","肾积水"],"a":3,"e":"肾细胞癌可分泌促红细胞生成素样物质引起红细胞增多，同时出现血尿、腰痛及腹部肿块三联征。肾上腺肿瘤多引起高血压与低血钾，卵巢癌少见此表现。"},{"q":"某人夜间走山路时，发现有一黑影尾随而至，随即他心跳呼吸加快、拼命奔跑。此时其机体内主要发生","o":["交感－肾上腺皮质兴奋","交感－肾上腺髓质兴奋","肾素－血管紧张素分泌增多","假性神经递质分泌增多","血管加压素分泌增多"],"a":1,"e":"恐惧应激时交感神经兴奋，肾上腺髓质释放肾上腺素及去甲肾上腺素，出现心跳呼吸加快、血压升高、瞳孔扩大。肾上腺皮质激素起效慢，肾素-血管紧张素主要调节水盐。"},{"q":"某中年男性患者，有胃溃疡病史多年，3小时前突然上腹部疼痛，继而全腹疼痛。本例应首先考虑的是","o":["胃溃疡出血","胃溃疡穿孔","幽门梗阻","胃溃疡癌变","胃酸刺激溃疡面引起疼痛"],"a":1,"e":"溃疡病史者突发上腹剧痛并迅速波及全腹，为溃疡穿孔后胃肠内容物漏入腹腔引起弥漫性腹膜炎。溃疡出血表现为呕血与黑便，幽门梗阻以呕吐宿食为主。"},{"q":"患者，女，12岁。临床诊断为快速进行性肾小球肾炎，该疾病最具特征性的病变是","o":["基膜增厚","肾小球血管袢坏死","肾血管内膜纤维化","新月体形成","系膜细胞增生"],"a":3,"e":"快速进行性肾小球肾炎的组织学特征是球囊壁层上皮细胞增生伴单核细胞渗出，形成新月体，压迫毛细血管丛并致球囊腔闭塞。基膜增厚见于膜性肾病。"},{"q":"患者，男，27岁。突发高热、寒战、头痛、全身酸痛，尤以肾区疼痛为甚。面色潮红，呈醉酒貌。全身皮肤散在瘀点、瘀斑，肾区叩痛。入院后抢救无效死亡。尸检：全身皮肤及黏膜散在瘀点及瘀斑，睑结膜充血、出血。肺、肾表面可见点状出血，右心房出血。镜检：肾小球毛细血管充血，肾小管上皮细胞变性、坏死，肾小管管腔内可见各种管型，肾间质高度充血、水肿和弥漫性出血。可考虑诊断为","o":["伤寒","大叶性肺炎","流行性出血热","钩端螺旋体病","急性肾盂肾炎"],"a":2,"e":"发热、醉酒貌、皮肤瘀点瘀斑及肾区叩痛，尸检见肾间质弥漫性出血与肾小管坏死，为汉坦病毒经鼠类传播的流行性出血热。钩端螺旋体病以腓肠肌压痛、黄疸为特点。"},{"q":"一心源性休克患者，血气测定结果如下：pH 7.31，其细胞外哪种离子的浓度易增加","o":["K+","Na+","Cl-","HCO3-","HPO42-"],"a":0,"e":"心源性休克时组织灌注不足、乳酸堆积致代谢性酸中毒，细胞内外H+与K+交换增强，钾自细胞内移出，故细胞外K+浓度升高。酸中毒时HCO3-降低而非升高。"},{"q":"患者，女，59岁。下肢静脉血栓4年，治疗取血栓，触之质硬、致密，切割有砂砾感。该血栓可能继发的病理变化是","o":["机化","化生","纤维化","玻璃样变","钙化"],"a":4,"e":"血栓机化后纤维组织玻璃样变并钙盐沉积，质地变硬、切面有砂砾感，即血栓钙化，静脉内者称静脉石。血栓软化则质地变软、易脱落形成栓塞。"},{"q":"某急性肾功能衰竭患者血气分析结果为pH：7.18，PaCO2：30mmHg，HCO3-：9mmol/L，该患者的心肌收缩力","o":["先增强后减弱","增强","不变","减弱","先减弱后增强"],"a":3,"e":"pH7.18、HCO3-9mmol/L、PaCO2代偿性降低，为重度代谢性酸中毒；酸中毒使心肌收缩力减弱、心肌对儿茶酚胺反应性下降，并可诱发心律失常。"},{"q":"患者，男，43岁。劳累时心悸、气短两年，加重伴夜间不能平卧3天。查体：血压120/75mmHg，心率100次/分，皮肤温度降低，双下肢水肿。胸部X线提示心脏向左侧扩大。上述哪项表现不属于心功能不全的代偿反应","o":["心率加快","血压正常","心脏扩大","皮肤温度降低","双下肢水肿"],"a":4,"e":"心率加快与心脏扩大属心功能不全的代偿反应，血压维持正常亦为代偿表现；皮肤温度降低由外周血管收缩、血液重分布所致。双下肢水肿是静脉淤血的结果，属失代偿表现。"},{"q":"11 岁儿童，锁骨上淋巴结肿大，约1.5cm×2.0cm ，活动度尚好。表面光滑，切面细腻、无出血坏死。镜下淋巴结结构消失，在大量的淋巴细胞当中可见到少量的 R-S 细胞及典型的镜影细胞。该例的正确诊断为","o":["外周T细胞淋巴瘤","非霍奇金淋巴瘤","小淋巴细胞淋巴瘤","霍奇金淋巴瘤","巨大淋巴结病"],"a":3,"e":"淋巴结结构破坏，淋巴细胞背景中见少量R-S细胞及典型镜影细胞，为霍奇金淋巴瘤的诊断依据。非霍奇金淋巴瘤无R-S细胞，需依靠免疫表型与遗传学确诊。"},{"q":"患者，男，63岁。因心慌胸闷2年，咳嗽气急30天入院。既往有高血压病，近一个月来症状加重，夜间不能平卧，咳嗽、咳粉红色泡沫状痰。X线检查双肺纹理增粗，心界扩大。患者肺部可能有哪些变化","o":["肺淤血","肺结核","肺梗死","间质性肺炎","大叶性肺炎"],"a":0,"e":"高血压、左心衰竭患者夜间不能平卧、咳粉红色泡沫痰，X线示双肺纹理增粗，为急性肺淤血、肺水肿。肺淤血时肺泡壁毛细血管扩张充血，肺泡腔内有水肿液及红细胞。"},{"q":"患儿，男，3岁。无任何诱因突发剧烈阵发性腹痛伴恶心、呕吐1天入院手术。术中见肠套叠。套叠肠管扩张，颜色暗红，局部发黑坏死。肠管的病变可诊断为","o":["肠缺血性梗死","肠出血性梗死","慢性肠炎","肠结核","肠动脉性充血"],"a":1,"e":"肠套叠使肠系膜静脉受压、静脉回流受阻而动脉仍通畅，肠管高度淤血、暗红发黑并坏死，为出血性梗死。贫血性梗死见于脾、肾等组织致密、侧支循环少的器官。"},{"q":"某科技工作者长期处于超负荷紧张工作状态，近期因家庭问题出现精神烦躁、情绪焦虑，出现心前区不适。其最不可能发生的心血管系统改变是","o":["血压升高","心肌梗死","心绞痛","二尖瓣狭窄","心律失常"],"a":3,"e":"长期精神紧张与焦虑使交感神经兴奋、血压升高、冠状动脉痉挛，可诱发心绞痛、心肌梗死及心律失常。二尖瓣狭窄由风湿热反复发作引起，与精神应激无关。"},{"q":"患儿，男，8岁。约一周前出现喉咙痛，两天前开始发热，体温38.8°C，恶心和呕吐。尿量减少，尿液呈暗色、烟熏色，血压略高，手足和眼周出现水肿。该患儿最可能患有的疾病是","o":["膜性肾小球病","新月体性肾小球肾炎","系膜增生性肾小球肾炎","IgA肾病","急性弥漫性增生性肾小球肾炎"],"a":4,"e":"儿童链球菌感染后1～2周出现血尿、少尿、水肿及高血压，为急性弥漫性增生性肾小球肾炎，由免疫复合物沉积致毛细血管内皮细胞和系膜细胞弥漫增生。"},{"q":"患者，女，28岁。近两天出现尿频、尿急、尿痛，体温升高到38.2°C，尿培养有大肠杆菌菌群生长，使用抗生素后体温下降，症状好转，她最有可能患有的疾病是","o":["急性弥漫性增生性肾小球肾炎","尿路上皮癌","子宫内膜异位","急性肾盂肾炎","慢性肾盂肾炎"],"a":3,"e":"育龄女性出现尿频尿急尿痛伴发热，尿培养大肠杆菌生长，抗菌治疗有效，为急性肾盂肾炎，是肾盂、肾间质及肾小管的化脓性炎。肾小球肾炎无尿路刺激征及菌尿。"},{"q":"一位32岁女性近两天出现尿频、尿急、尿痛，体温升高到38.5°C，尿培养有大肠杆菌菌群生长，使用抗生素后体温下降，症状好转。之后症状反复发作，迁延数载，她最有可能发展为以下哪种疾病","o":["慢性硬化性肾小球肾炎","膀胱炎","子宫内膜异位","肾细胞癌","慢性肾盂肾炎"],"a":4,"e":"急性肾盂肾炎反复发作、迁延数载，可发展为慢性肾盂肾炎，表现为肾间质纤维化、瘢痕形成及肾盂肾盏变形，是慢性肾衰竭的常见原因，反复感染与反流是慢性化基础。"},{"q":"患者，女，43岁。无明显诱因出现头痛、癫痫发作入院。入院后行头颅MRI显示左侧额叶、颞叶占位性病变，PET-CT示颅内多发不规则低密度灶，基因检测显示p53基因突变。上述检查结果提示病人可能患有","o":["胶质瘤","脑膜瘤","神经纤维瘤","神经鞘瘤","室管膜瘤"],"a":0,"e":"中年患者以癫痫、头痛起病，额颞叶占位并伴TP53突变，符合成人型弥漫性胶质瘤，好发于大脑半球。脑膜瘤为脑外良性肿瘤，边界清楚并可见脑膜尾征。"},{"q":"男性，50岁，高血压病史20年。近1月来，血压升高至180/110mmHg，出现头痛、头晕、眼花，有时恶心、呕吐，甚至意识模糊。符合本患者疾病的描述是","o":["脑出血","脑梗死","高血压危象","恶性高血压","心肌梗死"],"a":2,"e":"血压急剧升至180/110mmHg，出现头痛、头晕、眼花、恶心呕吐及意识模糊，为高血压危象（高血压脑病），由脑内细动脉痉挛及脑水肿所致，尚无局灶性神经体征。"},{"q":"患儿，男，4岁。因突发高热、惊厥、昏迷被幼儿园老师紧急送到医院急诊。查体未见皮肤、黏膜出血点或瘀斑。询问老师得知，近期幼儿园有小朋友“拉肚子”。该患儿最可能的诊断是","o":["流行性出血热，失血性休克","受到惊吓，神经源性休克","先天性心脏病，心源性休克","暴发型流脑，感染性休克","中毒性菌痢，感染性休克"],"a":4,"e":"幼儿突发高热、惊厥、昏迷而无皮肤瘀点，同期有腹泻患儿接触史，符合中毒性细菌性痢疾引起的感染性休克。暴发型流脑必有皮肤黏膜瘀点瘀斑。"},{"q":"一尸检标本，见肾内细动脉壁呈均质、红染，原有结构消失，最有可能的病理变化是","o":["脂肪变","细胞水肿","玻璃样变","黏液样变","淀粉样变"],"a":2,"e":"肾内细动脉壁呈均质红染、原有结构消失，为血浆蛋白沉积所致的细动脉玻璃样变，是良性高血压的基本病变。细胞水肿表现为细胞肿大、胞质疏松淡染。"},{"q":"患儿，男，8岁。暑假随父母到乡下奶奶家居住了2周。奶奶家养了鸡、鹅等家禽和猪、牛等家畜。在奶奶家居住期间曾多次被蚊子叮咬。回家后出现高热、嗜睡、抽搐、昏迷。该患儿最可能的诊断是","o":["流行性脑脊髓膜炎","流行性乙型脑炎","急性支气管炎","结核性脑膜炎","脑脓肿"],"a":1,"e":"夏季蚊虫叮咬并接触家禽家畜后出现高热、嗜睡、抽搐、昏迷，为乙型脑炎病毒经蚊传播的流行性乙型脑炎，病变以脑实质神经细胞变性坏死及筛状软化灶为特征。"},{"q":"某患者行阑尾切除术后，其阑尾送病理检查。镜下可见阑尾各层均有中性粒细胞浸润，血管明显扩张充血，未见组织坏死或增生性改变，该患者可诊断为","o":["急性单纯性阑尾炎","急性蜂窝织炎性阑尾炎","急性坏疽性阑尾炎","慢性阑尾炎","坏疽性阑尾炎"],"a":1,"e":"阑尾各层均有中性粒细胞弥漫浸润、血管扩张充血，为急性蜂窝织炎性（化脓性）阑尾炎。单纯性阑尾炎病变多限于黏膜及黏膜下层，坏疽性者出现广泛出血坏死。"},{"q":"患者，男，43岁。突然出现大咯血，少尿，肉眼血尿，实验室检查：血肌酐、尿素氮水平升高，抗GBM抗体阳性，尿常规发现红细胞、蛋白质均阳性。该患者最可能患有","o":["急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","IgA肾病","微小病变性肾病","膜性肾小球病"],"a":1,"e":"抗GBM抗体阳性、肺出血伴血尿及肾功能急剧恶化，为肺出血肾炎综合征（Goodpasture综合征），肾小球内新月体形成，属急进性肾小球肾炎Ⅰ型。"},{"q":"以下哪项不是大面积烧伤患者形成静脉内血栓的原因","o":["浆液渗出引起血浆浓缩","进食减少致白蛋白水平降低","卧床治疗期间血流缓慢","组织因子释放入血引起血液凝固性增高","皮肤烧伤引起血管壁损伤"],"a":1,"e":"大面积烧伤后血浆大量渗出致血液浓缩、血流缓慢，组织因子释放及血管壁损伤使血液凝固性增高，卧床又致血流淤滞，均促进静脉血栓形成。白蛋白降低只引起水肿。"},{"q":"患者，男，46岁。吸烟史20年，每日2～3包。近日咳嗽加重。支气管黏膜活检，可见黏膜被覆鳞状上皮，细胞无异型性。此种病理变化属于","o":["支气管黏膜萎缩","支气管黏膜鳞状上皮化生","支气管黏膜鳞状上皮增生","支气管鳞状细胞癌","支气管黏膜肥大"],"a":1,"e":"吸烟等刺激使支气管黏膜柱状上皮被复层鳞状上皮取代，细胞无异型性，为鳞状上皮化生。若细胞异型性明显并突破基膜，则诊断为鳞状细胞癌。"},{"q":"患者，女，40岁。两年前患胃癌并行胃大部切除术。三个月前体检B超提示右卵巢肿块，行卵巢切除术。卵巢标本活检，镜下示印戒细胞癌，并见低分化腺癌。该患者的卵巢病变可能是","o":["胃癌直接蔓延","胃癌淋巴道转移","胃癌血道转移","胃癌种植性转移","原发性卵巢癌"],"a":3,"e":"胃癌细胞侵及浆膜后脱落，种植于卵巢表面生长，形成双侧卵巢印戒细胞癌，即Krukenberg瘤，属种植性转移。血道转移多至肝、肺，淋巴道转移至左锁骨上淋巴结。"},{"q":"患儿，男，4岁。因咳嗽、咳痰伴喘息3天，以支气管肺炎收入院。入院查体：体温39℃，呼吸30次/分，心率130次/分，口周青紫，双肺底可闻及湿性啰音，肝脏肋下3cm，下肢轻度水肿，该患儿最可能的诊断为支气管肺炎合并了","o":["左心衰竭","右心衰竭","全心衰竭","呼吸衰竭","急性心肌炎"],"a":1,"e":"支气管肺炎患儿出现肝大、下肢水肿及心率增快，提示并发右心衰竭，由肺循环阻力增高、右心负荷加重所致。左心衰竭以肺淤血、咳粉红色泡沫痰为主。"},{"q":"患者，男，35岁。10年前诊断为急性乙型病毒性肝炎。最近B超显示，肝脏体积缩小，脾脏肿大，食管-胃底静脉曲张。患者可能的诊断是","o":["门脉性肝硬化","坏死后性肝硬化","血吸虫性肝硬化","淤血性肝硬化","胆汁性肝硬化"],"a":0,"e":"乙型肝炎病史十年，肝脏缩小、脾大及食管胃底静脉曲张，为肝炎后小结节型肝硬化（门脉性肝硬化），门静脉高压症状突出。血吸虫性肝硬化有疫水接触史。"},{"q":"肠伤寒患者，发热 2 天后，体温开始下降，伴周身大汗，此时治疗上应特别注意","o":["休息，吸氧","补充营养物质","补充维生素","补充水分和适量的电解质，防止脱水","药物解热"],"a":3,"e":"伤寒退热期大量出汗可致失水及电解质丢失，甚至虚脱，故应补充水分和适量电解质。此期肠道病变处于溃疡期，还须警惕肠出血与肠穿孔。"},{"q":"患者，女，56岁。患高血压病数年。近半月来，患者下肢水肿明显，尿中出现大量泡沫并不易消退。患者尿液检查可能发现","o":["尿蛋白+～++","白细胞+++","红细胞+++","脓细胞+++","尿比重升高"],"a":0,"e":"长期高血压致肾小动脉硬化、滤过屏障受损而出现蛋白尿，尿中泡沫多且不易消退，尿蛋白多为+～++。大量蛋白尿见于肾病综合征，白细胞及脓细胞增多提示感染。"},{"q":"患者，男，50岁。右腹股沟疝，经疝修补术后，伤口抗拉力强度达到顶点的时间是","o":["一周","三周","五周","二个月","三个月"],"a":4,"e":"伤口愈合1个月时表皮结构基本恢复，胶原纤维持续增多，抗拉力强度于3个月达到顶点，此后不再明显增加。瘢痕组织抗拉力始终弱于正常皮肤。"},{"q":"患者，男，22岁。半月前感冒，咽部肿痛，经治疗后好转。但尿液镜检显示：血尿(++++)，蛋白(±)，肾组织活检免疫荧光镜下显示：系膜区IgA 和 C3大量块状沉积，可诊断为","o":["IgA肾病","系膜增生性肾小球肾炎","急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","膜性肾小球病"],"a":0,"e":"上呼吸道感染后出现血尿，免疫荧光示系膜区IgA及C3呈团块状沉积，为IgA肾病。急性弥漫性增生性肾炎免疫荧光呈粗颗粒状沿基膜沉积。"},{"q":"患者，男，48岁。临床反复出现发热、乏力、体重下降、全身淋巴结肿大。肢体、面部反复出现皮损斑块，近期腭部、牙龈也出现斑块，活检为血管肉瘤（Kaposi肉瘤）。该患者最可能患有的疾病是","o":["系统性硬化","梅毒","黏膜皮肤念珠菌病","AIDS","霍奇金淋巴瘤"],"a":3,"e":"AIDS患者免疫缺陷，约30%发生卡波西肉瘤，表现为皮肤黏膜多发性斑块、结节，并伴发热、消瘦及全身淋巴结肿大。霍奇金淋巴瘤无此皮损及严重免疫缺陷。"},{"q":"患者，男，65岁。患糖尿病10余年，昏迷入院。化验尿常规：尿蛋白（+),葡萄糖（+++），酮体（+）。入院后注射胰岛素72单位，并输入0、9%NaCL及乳酸钠，患者神志逐渐清楚，呼吸平稳，但出现烦躁不安，心律不齐等表现。实验室检查除出现血钾偏低外，还可能出现","o":["低钠血症","低钙血症","高钠血症","高镁血症","低镁血症"],"a":4,"e":"糖尿病酮症酸中毒治疗后，胰岛素使葡萄糖和钾进入细胞，补液利尿又排出镁，故血镁降低，出现烦躁、心律不齐。低钙血症以手足搐搦为特征。"},{"q":"某球迷在世界杯比赛期间，高度关注自已支持的球队，熬夜看球，情绪随着球队的成绩而激烈变化。赛程进行1周后，该球迷出现腹痛、腹泻与便秘交替、食欲差。至世界杯赛结束后约1周，上述症状消失。该球迷最可能发生的是","o":["肠易激综合征","消化不良","急性肠炎","肠道肿瘤","慢性胃炎"],"a":0,"e":"长期精神紧张、作息紊乱后出现腹痛、腹泻与便秘交替及食欲差，症状随应激解除而消失且无器质性病变，符合肠易激综合征。急性肠炎有明确感染及水样腹泻。"},{"q":"患儿，男，5岁。因发热，呕吐，皮肤有出血点3天入院。治疗中出血点逐渐增多呈片状，出血点涂片检查见脑膜炎双球菌。血压由入院时的92/64mmHg降至60/40mmHg。进一步检查确诊为DIC，下述检查中哪项不支持DIC诊断","o":["血小板计数明显降低","凝血酶原时间延长","纤维蛋白原含量降低","3P试验阳性","凝血酶原时间缩短"],"a":4,"e":"DIC时凝血因子与血小板大量消耗，故血小板减少、凝血酶原时间延长、纤维蛋白原降低，继发性纤溶亢进使3P试验阳性。凝血酶原时间缩短不支持DIC诊断。"},{"q":"患者，女，30岁。出现心悸2年，1个月前因牙痛拔牙后，开始发热，全身乏力，体检：皮肤有出血点，脾大，心尖区可闻及杂音。该患者最可能患有","o":["风湿病活动期","感冒、肺部轻微感染","亚急性感染性心内膜炎","风湿性心瓣膜病","急性感染性心内膜炎"],"a":2,"e":"拔牙后菌血症使原有瓣膜病变处形成赘生物，出现发热、乏力、皮肤出血点、脾大及心脏杂音，为亚急性感染性心内膜炎。急性者多由金黄色葡萄球菌引起，起病急、病情重。"},{"q":"某患者血氧指标检查为：动脉血氧分压100mmHg（正常为100mmHg），静脉血氧分压为55mmHg（正常为40mmHg），血氧容量20ml/dl（正常为20ml/dl），动脉血氧饱和度95%，动静脉氧含量差2、8ml/dl(正常为5ml/dl)。，此患者可有哪些类型缺氧","o":["低张性缺氧","循环性缺氧","血液性缺氧","组织性缺氧","淤血性缺氧"],"a":3,"e":"动脉血氧分压及血氧容量正常，而静脉血氧分压升高、动静脉氧含量差明显减小，说明组织细胞利用氧障碍，属组织性缺氧。循环性缺氧时静脉氧分压降低、氧差增大。"},{"q":"患儿，男，6岁。 脓血便8天，高热3天，多饮多尿，近两天乏力，呼吸困难2小时入院。体检，神志不清，口唇发绀，腹胀，肠鸣音消失，四肢呈迟缓性瘫痪，血钠140mmol/L，血钾2、6mmol/L，该患者最可能的诊断是","o":["低钠血症","低钙血症","低钾血症","高钾血症","高钠血症"],"a":2,"e":"脓血便伴高热、多尿，随后出现腹胀、肠鸣音消失及四肢弛缓性瘫痪，血清钾2.6mmol/L，为低钾血症引起的肠麻痹与骨骼肌无力，严重腹泻丢钾是主要原因。"},{"q":"患者，男，60岁。因胃癌广泛转移而死亡。尸体解剖检查，心脏重200g。切片检查心肌细胞核两侧可见黄褐色细颗粒状色素，此色素最可能是","o":["黑色素","胆色素","含铁血黄素","脂褐素","前角蛋白聚集"],"a":3,"e":"心肌细胞核两侧的黄褐色细颗粒为脂褐素，是自噬溶酶体内未被消化的细胞器碎片残体，在老年人及恶性肿瘤等消耗性疾病患者的萎缩心肌中蓄积，又称消耗性色素。"},{"q":"患者，男，68岁。既往患冠心病10余年，近日出现慢性充血性心力衰竭合并慢性肺淤血。患者咳嗽、咳痰，呼吸困难，其特征性痰中应出现","o":["肺泡上皮细胞","心力衰竭细胞","异物巨细胞","中性粒细胞","朗汉斯巨细胞"],"a":1,"e":"慢性肺淤血时巨噬细胞吞噬红细胞，血红蛋白分解形成含铁血黄素颗粒，即心力衰竭细胞，可随痰咳出。该细胞的出现是慢性肺淤血的形态学标志。"},{"q":"患者，男，60岁。长期以来感觉上腹胀，出现空腹痛以及夜间痛，大便潜血阳性，幽门螺杆菌阳性。可诊断为","o":["早期胃癌","胃溃疡","慢性浅表性胃炎","十二指肠溃疡","慢性萎缩性胃炎"],"a":3,"e":"空腹痛及夜间痛、进食后缓解、便潜血阳性及幽门螺杆菌阳性，符合十二指肠溃疡。早期胃癌多无明显症状，胃溃疡多为餐后痛。"},{"q":"患者，女，30岁。腰椎结核并在腰椎旁形成冷脓肿，破溃后流脓不止。此处已形成","o":["空洞","瘘管","溃疡","窦道","糜烂"],"a":3,"e":"腰椎结核形成的冷脓肿破溃后，只有一端开口通向体表的盲管，为窦道。瘘管两端均有开口，分别连接两个腔隙或连接内脏与体表。"},{"q":"患者，男。1天前因煤气爆炸造成面部、前胸及上肢Ⅱ～Ⅲ度烧伤，面积达 40%，当地医院给予大量5%的葡萄糖溶液。次日转入某院，入院实验室检查血清钠 110mmol/L ，渗透压250mOsm/L 。该患者出现的水、钠代谢紊乱类型是","o":["水中毒","等渗性脱水","低渗性脱水","高渗性脱水","水肿"],"a":2,"e":"烧伤后大量输入5%葡萄糖液，水分过多而钠补充不足，血清钠110mmol/L、血浆渗透压降低，符合低渗性脱水。水中毒时细胞外液容量增多，无眼窝凹陷等脱水体征。"},{"q":"中年女性，化验指标提示甲状腺功能低下，手术切除标本甲状腺弥漫性对称性肿大，稍呈结节状，质较韧，镜下见甲状腺正常结构破坏，有大量的淋巴细胞浸润、甲状腺滤泡萎缩。滤泡上皮常有嗜酸性变、纤维组织增生和淋巴滤泡形成，该患者最有可能的诊断是","o":["桥本甲状腺炎","慢性纤维性甲状腺炎","结节性甲状腺肿","乳头状癌","甲状腺腺瘤"],"a":0,"e":"中年女性甲状腺弥漫对称性肿大、质韧，镜下滤泡萎缩、大量淋巴细胞浸润及淋巴滤泡形成，伴嗜酸性变和纤维增生，甲状腺功能低下，为桥本甲状腺炎。慢性纤维性甲状腺炎质硬如木、与周围粘连。"},{"q":"男性，62岁，因肺心病伴发呼吸衰竭入院，入院检查：血气结果如下：PaO2：30mmHg，PaCO2：60mmHg，经氧疗后患者病情恶化，血气数值变为：PaO2：70mmHg，PaCO2：80mmHg，分析原因最可能的是","o":["感染加重","气道阻力增加","心力衰竭加重","周围循环衰竭","氧疗方法不当"],"a":4,"e":"慢性阻塞性肺疾病呼吸衰竭时，高浓度吸氧解除了低氧对外周化学感受器的驱动，呼吸进一步抑制，CO2潴留加重而病情恶化，故应低浓度持续吸氧。"},{"q":"患儿，女，5岁。因倦怠、食欲减退、潮热、盗汗就诊。该患儿呈营养不良体征，经检查发现结核菌素试验为阳性，X线胸片显示肺部呈哑铃状阴影，未见咳嗽、咯血及其他异常。考虑诊断为","o":["干酪样肺炎","小叶性肺炎","原发性肺结核","支原体肺炎","病毒性肺炎"],"a":2,"e":"儿童结核菌素试验阳性，X线示肺部哑铃状阴影，由原发灶、结核性淋巴管炎及肺门淋巴结炎构成原发复合征，为原发性肺结核。干酪样肺炎为大片干酪样坏死实变。"},{"q":"HE染色切片，镜下见癌细胞弥漫浸润于胃壁全层，癌细胞胞质内有蓝染物质，核偏于一侧呈印戒样。该切片应诊断为","o":["印戒细胞癌","鳞癌","腺鳞癌","腺瘤","未分化癌"],"a":0,"e":"癌细胞胞质内充满黏液并将核挤向一侧，呈印戒样，弥漫浸润胃壁全层，为印戒细胞癌，属低黏附性癌。鳞癌有角化珠及细胞间桥，未分化癌无腺管及黏液。"},{"q":"患者，男，55岁。慢性支气管炎、肺气肿10年。最近出现下肢水肿，呼吸气促、乏力，颈静脉怒张。同时B超显示，肝脏体积变小、脾脏肿大。患者肝脏可能出现的病变是","o":["门脉性肝硬化","坏死后性肝硬化","血吸虫性肝硬化","淤血性肝硬化","胆汁性肝硬化"],"a":3,"e":"慢性支气管炎、肺气肿致肺动脉高压和右心衰竭，长期肝淤血使肝细胞萎缩、纤维组织增生，形成淤血性肝硬化（心源性肝硬化）。门脉性肝硬化由肝炎或酒精引起。"},{"q":"一慢性阻塞性肺部疾患的病人继发心力衰竭，血气分析结果表现为pH：7.31，PaCO2：62mmHg， HCO3-：30mmol/L，可诊断为","o":["代谢性酸中毒","呼吸性酸中毒","代谢性碱中毒","呼吸性碱中毒","呼吸性酸中毒合并代谢性碱中毒"],"a":1,"e":"慢性阻塞性肺疾病继发心衰，PaCO2 62mmHg伴pH降低，HCO3-代偿性升高至30mmol/L，符合慢性呼吸性酸中毒失代偿。代谢性酸中毒时HCO3-降低。"},{"q":"患者会出现典型的恐水、怕风、咽喉肌痉挛、进行性瘫痪等症状，应考虑诊断为","o":["狂犬病","流行性脑脊髓膜炎","钩端螺旋体病","伤寒","流行性乙型脑炎"],"a":0,"e":"狂犬病病毒经咬伤伤口沿周围神经逆行入脑，引起恐水、怕风、咽喉肌痉挛及进行性瘫痪，镜下海马及锥体细胞胞质内可见内氏小体。乙型脑炎以高热、抽搐、昏迷为主。"},{"q":"患者，男，58岁。因进行性体弱、疲劳，劳力性呼吸困难1周入院。体检示心律不齐，双侧肺底部可闻及水泡音。胸片示肺水肿。给予地高辛和呋塞米治疗，3天后出现头晕，四肢肌肉无力、腹胀等表现。EKG显示T波低平，ST段降低，该患者可能出现的电解质紊乱类型是","o":["低钠血症","低钙血症","低钾血症","高钾血症","高钠血症"],"a":2,"e":"地高辛与呋塞米合用，呋塞米抑制肾小管重吸收钾，加之摄入不足，致低钾血症，出现肌无力、腹胀、T波低平及ST段降低。低钠血症以神经系统症状为主。"},{"q":"患者，男，25岁。下肢骨折后，石膏固定2个月，使患侧肢体变细，肌肉萎缩，病理诊断属于","o":["压迫性萎缩","内分泌性萎缩","营养不良性萎缩","去神经性萎缩","失用性萎缩"],"a":4,"e":"肢体长期固定、工作负荷减少，肌肉蛋白质合成下降而分解增强，属失用性萎缩；骨折后石膏制动引起的肌萎缩即以失用为主要原因。"},{"q":"一患儿由于误吞了小玩具，出现呼吸困难症状。经检查玩具阻塞在中央气道的胸内段，患儿的呼吸困难表现为","o":["呼吸性呼吸困难","吸气性呼吸困难","呼吸和吸气均困难","呼吸和吸气困难交替出现","阵发性吸气困难"],"a":0,"e":"胸内段气管位于胸腔内，呼气时胸内压升高压迫管壁使管腔变窄，气流受阻，故出现呼气性呼吸困难；吸气时胸内负压使气道扩张，吸气相对顺利。"},{"q":"患者，女，55岁。数月前发现左肩部皮下有一肿物，活动度好。病理检查发现：送检组织似正常脂肪组织，呈不规则分叶状，由纤维间隔。该患者的病理诊断是","o":["脂肪瘤","平滑肌瘤","淋巴管瘤","囊腺瘤","纤维肉瘤"],"a":0,"e":"肿瘤由成熟脂肪细胞构成，呈不规则分叶状并有纤维间隔，形态与正常脂肪组织相似，符合脂肪瘤；该瘤好发于背、肩、颈及四肢近端皮下。"},{"q":"患者，女，34岁。孕10周时检查发现无胎心搏动，随行引产手术。术后第二天患者出现寒战、高热、呕吐等症。实验室检查：血红蛋白50g/L，白细胞总数26、6×109/L，中性粒细胞0.9。给予输血、抗感染等治疗，在交叉配血时发现患者外周血中有大量星型、盔型等形态各异的红细胞。该患者的贫血最有可能是","o":["感染性贫血","微血管病性溶血性贫血","失血性贫血","中毒性贫血","缺铁性贫血"],"a":1,"e":"外周血出现星形、盔形等破碎红细胞，提示红细胞在狭窄微血管内被纤维蛋白网切割破坏，属微血管病性溶血性贫血，常继发于DIC。"},{"q":"患者，男，56岁，农民。双下肢活动无力、头晕头痛2天，加重2小时入院。患者行走不稳伴言语不利，时有恶心，查头部CT示：左侧腔隙性脑梗死。下列哪项病理学描述是错误的","o":["为出血性梗死","属液化性坏死","梗死灶颜色灰白","可见脑软化灶","可形成胶质瘢痕"],"a":0,"e":"脑梗死属贫血性梗死，缺血后脑组织液化坏死形成灰白色软化灶，晚期由胶质细胞增生形成胶质瘢痕；仅静脉性淤血时才呈出血性梗死。"},{"q":"患者，女，20岁。长期腹泻。电子肠镜检查：结肠密布大小不等的息肉，多达100余个，有蒂或无蒂。单个肿物切除活检，病理报告为：管状腺瘤。请问，该患者的疾病描述最可能是","o":["结肠多发管状腺瘤，可能与遗传因素有关","结肠多发性腺瘤性息肉，可能与免疫因素有关","结肠腺瘤性息肉病，可能与遗传因素有关","结肠腺瘤性息肉病，可能与免疫因素有关","结肠多发性腺瘤性息肉，可能与环境因素有关"],"a":2,"e":"结肠内息肉逾百个、活检为管状腺瘤，符合家族性腺瘤性息肉病；该病由APC基因胚系突变引起，属常染色体显性遗传，癌变率极高。"},{"q":"患者，女，4岁。于外阴部发现一葡萄样肿物。病理检查发现：送检组织由不同分化阶段的横纹肌母细胞组成。该患者的病理诊断是","o":["脂肪瘤","平滑肌肉瘤","横纹肌肉瘤","尿路上皮癌","纤维肉瘤"],"a":2,"e":"肿瘤由不同分化阶段的横纹肌母细胞构成，胞质红染、可见横纹，为横纹肌肉瘤；该瘤好发于10岁以下儿童的头颈部及泌尿生殖道。"},{"q":"患者，男，35岁。食用海鲜后出现黄疸，肝功能异常。据调查，购买同一批海鲜的多人出现相同症状。实验室检查，HAV（+）。病人可能的诊断是","o":["甲型病毒性肝炎","乙型病毒性肝炎","丙型病毒性肝炎","丁型病毒性肝炎","戊型病毒性肝炎"],"a":0,"e":"HAV为单链RNA病毒，经粪-口途径传播，食用污染海产品可引起暴发流行，多表现为急性黄疸型肝炎，一般不转为慢性。"},{"q":"患者，男，42岁。长期以来感觉上腹胀，食欲不振，体检未见明显异常，胃镜检查显示：黏膜充血、水肿，表面有灰白色或灰黄色分泌物。诊断为","o":["早期胃癌","胃溃疡","慢性浅表性胃炎","慢性萎缩性胃炎","慢性肥厚性胃炎"],"a":2,"e":"胃镜下黏膜充血、水肿并覆灰白或灰黄黏液性渗出物，而腺体保持完整无萎缩，符合慢性浅表性胃炎，病变以胃窦部最常见。"},{"q":"男性，65岁，查体发现动脉粥样硬化。请问下列检查指标中升高的可能性最小的是","o":["TG","HDL","LDL","ox-LDL","VLDL"],"a":1,"e":"HDL对动脉粥样硬化有预防作用，可抗氧化并竞争性抑制LDL与内皮受体结合；AS患者以LDL、VLDL、TG升高和HDL降低为特征，故HDL升高可能性最小。"},{"q":"患儿，男，9岁，主诉头痛、头晕乏力，半月前曾患有急性咽喉炎，体检发现其面部水肿，血压160/100 mmHg。少尿，尿液分析显示血尿和轻度蛋白尿。他最可能患有的疾病是","o":["微小病变性肾小球病","新月体性肾小球肾炎","膜性肾小球病","急性弥漫性增生性肾小球肾炎","IgA肾病"],"a":3,"e":"咽部感染后约10天出现血尿、少尿、水肿和高血压，为急性肾炎综合征；病理上内皮细胞和系膜细胞弥漫增生伴中性粒细胞浸润，即急性弥漫性增生性肾小球肾炎。"},{"q":"患者，女，50岁。胃痛半年。胃镜检查胃窦部有一3cm×4cm的不规则溃疡；B超示双侧卵巢肿大。病理检查发现，卵巢活检病理图像与胃活检图像一致。下列推测中哪一项是错误的","o":["胃内病灶是原发灶","卵巢病灶为转移灶","卵巢转移灶为种植性转移所致","患者患有胃癌和卵巢癌","胃癌伴卵巢转移"],"a":3,"e":"双侧卵巢与胃壁病变形态一致，提示卵巢为胃黏液腺癌转移所致（Krukenberg瘤），原发灶在胃，属一癌两处而非两种原发癌。"},{"q":"患者，男，54岁。体检时发现血压升高，160/98mmHg。服药或休息后血压可降至正常。此患者血压升高可能是由于","o":["细动脉硬化","全身细小动脉痉挛","大动脉粥样硬化","动脉中层钙化","广泛性细小动脉坏死"],"a":1,"e":"血压升高而休息或服药后可降至正常，动脉尚无器质性改变，属高血压功能紊乱期的全身细小动脉间歇性痉挛；细动脉硬化形成后血压即失去波动性。"},{"q":"某患者血气分析结果为：pH 7.20，PaCO2 71mmHg，HCO3ˉ 27mmol/L，最可能的酸碱平衡紊乱类型是","o":["无酸碱平衡紊乱","代偿性酸中毒","代偿性碱中毒","失代偿性酸中毒","失代偿性碱中毒"],"a":3,"e":"PaCO2显著升高而HCO3-仅轻度升高，pH低于7.35，为失代偿性呼吸性酸中毒；CO2潴留使pH下降，肾脏代偿尚未充分建立。"},{"q":"某糖尿病患者血气分析结果：pH：7.30，PaCO2：33mmHg，HCO3-：16mmol/L，血Na+：140mmol/L，Cl-：104mmol/L，K+：3.5mmol/L，可诊断为","o":["急性呼吸性酸中毒","慢性呼吸性酸中毒","AG正常型代谢性酸中毒","AG增高型代谢性酸中毒","呼吸性酸中毒合并代谢性酸中毒"],"a":3,"e":"AG=140-104-16=20mmol/L，明显增高，提示有机酸蓄积，为AG增高型代谢性酸中毒；糖尿病酮症酸中毒即属此型，Cl-正常可排除高氯性酸中毒。"},{"q":"肺结核患者发热 1 周，伴精神差，食欲下降，尿液检查时出现尿酮，其原因是","o":["糖原分解增强","脂肪分解增强","蛋白质分解增强","维生素消耗增多","皮肤、呼吸道水分蒸发增多"],"a":1,"e":"发热使分解代谢增强、糖原消耗，机体转而大量动员脂肪供能，脂肪酸氧化不全产生酮体，故尿酮阳性；蛋白质分解并不产生酮体。"},{"q":"一慢性肝炎、肝硬化并有严重肝功能不全的病人，急诊入院时出现意识障碍、手足抽搐等表现，提示出现了哪种酸碱平衡紊乱","o":["代谢性酸中毒","呼吸性酸中毒","呼吸性碱中毒","代谢性碱中毒","呼吸性酸中毒合并代谢性酸中毒"],"a":2,"e":"严重肝病时血氨等毒性物质刺激呼吸中枢使通气过度，CO2排出过多形成呼吸性碱中毒；碱中毒使血浆游离钙减少，故出现手足抽搐。"},{"q":"某男，60岁。因胃部不适、消瘦、贫血3个月入院。经胃镜活检诊断为胃腺癌。从抑制细胞增殖信号转导过弱的角度分析，其发生的分子基础最有可能是","o":["表皮生长因子受体过度表达","信号转导分子类蛋白异常表达","TGF-βII型受体突变","sis基因激活","int-2基因激活"],"a":2,"e":"TGF-β经II型受体传递抑制细胞增殖的信号，受体突变使抑制信号减弱，细胞增殖失控；该机制见于胃腺癌等消化道肿瘤，属抑癌通路失活。"},{"q":"患者，男，12岁。以慢性骨髓炎收入院。入院后病理检查发现：送检组织异型性明显，梭形或多边形，直接形成肿瘤性骨样组织。X线检查可见Codman三角。本病例最可能的诊断是","o":["脂肪瘤","骨肉瘤","横纹肌肉瘤","血管肉瘤","纤维肉瘤"],"a":1,"e":"肿瘤细胞异型性明显，直接形成肿瘤性骨样组织，并有Codman三角，是诊断骨肉瘤最重要的依据；该瘤好发于青少年长骨干骺端。"},{"q":"女性患者，23岁，近期多食，但人渐消瘦，出现心悸、多汗、怕热、易激动等症状，颈部肿大，眼球突出，其可能的临床诊断是","o":["Graves病","单纯性甲状腺肿","桥本甲状腺炎","Riedel甲状腺肿","甲状腺腺瘤"],"a":0,"e":"多食、消瘦、心悸、多汗、怕热、易激动伴甲状腺肿大和突眼，为甲状腺激素分泌过多的表现，符合弥漫性毒性甲状腺肿，由TRAb刺激TSH受体所致。"},{"q":"黄嘌呤脱氢酶转变为黄嘌呤氧化酶需要","o":["镁依赖性蛋白水解酶","锌依赖性蛋白水解酶","钙依赖性蛋白水解酶","铜依赖性蛋白水解酶","铁依赖性蛋白水解酶"],"a":2,"e":"缺血缺氧使细胞内钙升高，激活钙依赖性蛋白水解酶，使黄嘌呤脱氢酶转变为黄嘌呤氧化酶，后者催化次黄嘌呤生成尿酸并产生氧自由基。"},{"q":"不符合蕈样肉芽肿特点的描述是","o":["原发于皮肤","T细胞来源","形成Pautrier微脓肿","细胞核高度扭曲","好发于儿童"],"a":4,"e":"蕈样肉芽肿为原发于皮肤的成熟T细胞淋巴瘤，瘤细胞核高度扭曲，侵入表皮形成Pautrier微脓肿；多见于中老年，而非儿童。"},{"q":"患者，女，36岁。因车祸致股骨粉碎性骨折，整复时突然死亡，其原因最可能是","o":["脑动脉粥样硬化","伤口感染后引起脑膜脑炎","股静脉血栓形成","骨折源性脂肪栓塞","左心房球形血栓脱落"],"a":3,"e":"长骨骨折时骨髓脂肪滴入血，经静脉、右心进入肺动脉引起脂肪栓塞，可致猝死；整复时突然死亡尤应考虑此并发症。"},{"q":"患者，男，58岁。有慢性肝炎史20余年。近半年来恶心、乏力伴肝区疼痛。B超示肝右叶有一直径2cm大小的肿物，血液AFP阳性。肝穿刺活检显示：肿瘤细胞类似肝细胞，细胞间有丰富的血窦样腔隙。该患者最有可能的诊断是","o":["肝硬化","肝腺瘤","早期肝癌（小肝癌）","肝转移癌","肝胆管细胞癌"],"a":2,"e":"慢性肝病背景、AFP阳性、肝内2cm单发结节，镜下癌细胞似肝细胞且血窦丰富，符合小肝癌；直径小于3cm者属早期肝癌的范畴。"},{"q":"患者，男，20岁。剧烈运动时不慎扭伤左踝关节以致骨折，到骨伤科医院进行了及时良好的复位、固定后，其骨折部位最可能的结果是","o":["骨折处由软骨代替","骨折处由纤维组织代替","骨折处由骨组织代替，但不能恢复原状","骨折处完全愈合，恢复正常的结构和功能","骨折处由纤维组织、软骨组织、骨组织混合增生代替"],"a":3,"e":"血供良好、复位固定满意的单纯外伤性骨折，骨再生能力强，数月内可完全愈合，恢复正常结构和功能；纤维或软骨连接仅见于愈合不良时。"},{"q":"某溺水窒息患儿，血气分析结果为：pH 7.16，PaCO2 75mmHg，HCO3ˉ 26mmol/L，其主要依靠下列哪种方式代偿","o":["碳酸氢盐缓冲系统","血红蛋白的缓冲作用","肺的调节作用","肾脏的调节作用","骨骼的代偿作用"],"a":1,"e":"急性呼吸性酸中毒时肾脏代偿需数日才充分发挥，即刻的缓冲主要靠血红蛋白摄取H+并释放氧，故以血红蛋白的缓冲作用为主。"},{"q":"患者，男，65岁。确诊肝癌1年余。患者烟龄10多年，每天吸烟1包。有饮酒史20多年，每天约2两。喜食腌制食品。经常上夜班。与该患者肝癌发生关系最密切的致瘤因素是","o":["吸烟","饮酒","亚硝胺类物质","作息不规律","遗传因素"],"a":1,"e":"酒精在肝内代谢生成乙醛，引起酒精性肝炎和酒精性肝硬化，是肝细胞癌的重要致癌因子；本例饮酒史长、量大，与肝癌关系最密切。"},{"q":"患者，男，65岁。因骨折卧床数月，近一月来常咳嗽，并咳黄色黏脓痰。查体：双肺下叶可闻及湿啰音；X线片示双肺下叶不规则散在小片状模糊阴影。最有可能的诊断是","o":["大叶性肺炎","小叶性肺炎","慢性支气管炎","支气管扩张","支气管哮喘"],"a":1,"e":"长期卧床致肺下叶坠积性淤血，细菌在细支气管及其周围肺泡繁殖，形成以细支气管为中心的化脓性炎，X线呈散在小片状阴影，符合小叶性肺炎。"},{"q":"患者，女，74岁。由于长期卧床导致下肢深静脉血栓形成，若栓子脱落，最可能发生的是","o":["肺动脉栓塞","脾动脉栓塞","肾动脉栓塞","肝门静脉栓塞","肾静脉栓塞"],"a":0,"e":"下肢深静脉血栓脱落后经静脉、右心进入肺动脉，引起肺动脉栓塞；这是体循环静脉血栓最常见且最危险的后果。"},{"q":"患者，男，65岁。吸烟史40年，近一个月来咳嗽、痰中带血。X线示右肺近肺门处不规则阴影，边界不清，痰菌阴性，可能的诊断为","o":["慢性支气管炎","大叶性肺炎","小叶性肺炎","肺癌","炎性假瘤"],"a":3,"e":"长期吸烟、痰中带血，肺门附近出现边界不清的不规则肿块而痰菌阴性，符合中央型肺癌；炎性假瘤多有感染史且边界清楚。"},{"q":"患者，男，67岁。尿毒症并发肺部、泌尿系统的严重感染，下列哪项是患者并发感染的原因","o":["体液免疫受到明显抑制","细胞免疫受到明显抑制","B淋巴细胞数量相对减少","心衰致供血不足","负氮平衡致恶病质"],"a":1,"e":"尿毒症毒素抑制T淋巴细胞功能，细胞免疫明显受损，故易并发肺部及泌尿系统感染；体液免疫亦受累，但以细胞免疫抑制最为突出。"},{"q":"患者，女，50岁。发作性胸痛1个月，常放射至左肩，左臂内侧，每次发作含硝酸甘油后缓解。患者可能的诊断是","o":["心绞痛","心肌梗死","左心衰竭","心内膜炎","心外膜炎"],"a":0,"e":"发作性胸骨后疼痛向左肩及左臂内侧放射，含硝酸甘油可缓解，为心肌短暂缺血所致，符合心绞痛；疼痛持续不缓解则提示心肌梗死。"},{"q":"患者，女，53岁。因咳嗽及右侧胸痛不适入院，X线示右肺下叶近胸膜处见一直径3cm的球形阴影，边界不清，抗生素及抗结核治疗不见好转，痰脱落细胞学检查见可疑腺癌细胞。该患者最有可能的诊断是","o":["肺鳞状细胞癌","肺小细胞癌","肺结核","小叶性肺炎","肺腺癌"],"a":4,"e":"肿块位于胸膜下、边界不清，痰中查见腺癌细胞，符合周围型肺腺癌；腺癌多起源于较小支气管上皮，常累及胸膜。"},{"q":"患者，男，24岁。临床反复出现发热、乏力、肺部感染、体重下降、全身淋巴结肿大。血清示HIV-1阳性。该患者体内HIV-1攻击的细胞是","o":["CD4+T淋巴细胞","CD8+T淋巴细胞","B淋巴细胞","嗜酸性粒细胞","中性粒细胞"],"a":0,"e":"HIV包膜糖蛋白gp120与CD4分子结合，主要攻击CD4+T淋巴细胞，使其进行性减少，导致细胞免疫缺陷和机会性感染。"},{"q":"患者，男，23岁，持续高热伴腹泻8天，大便每天5~6次，偶有黏液，右下腹隐痛。体检：肝脏右肋下2cm，脾脏左肋下1cm，躯干背侧隐约可见米粒大小淡红色皮疹，压之退色。血液检查未见白细胞升高。大便检查见少许白细胞及脓细胞，培养无致病菌。应诊断为","o":["细菌性痢疾","阿米巴病","食物中毒","伤寒","急性肠炎"],"a":3,"e":"持续高热、相对缓脉、脾大、躯干玫瑰疹及白细胞不升高，为伤寒的典型表现；粪便培养阴性不能排除，肥达反应有助诊断。"},{"q":"患者，男，45岁。患风湿性心内膜炎10年，近日发热，白细胞增多，皮肤黏膜见出血点。住院治疗期间，医嘱绝对卧床休息。今晨病人自行起床，数分钟后突感头痛，呕吐，左下肢麻木，倒地死亡。该患者最可能的死因是","o":["心肌梗死","脑出血","肺动脉栓塞","肺炎","脑动脉栓塞"],"a":4,"e":"感染性心内膜炎的赘生物脱落后形成栓子，经左心进入体循环栓塞脑动脉而猝死；卧床后突然活动是栓子脱落的常见诱因。"},{"q":"某男孩，出生后即出现多尿、烦渴、多饮等症状，注射加压素后尿量不减少，尿比重不增加，血浆ADH浓度正常。患儿出现该病最可能的原因是","o":["精神因素","下丘脑神经垂体部位的肿瘤","神经细胞退行性病变","ADHV2受体合成减少或结构异常","ADH-神经垂体素运载蛋白基因突变"],"a":3,"e":"注射加压素后尿量与尿比重均无变化，而ADH水平正常，说明肾小管对ADH不反应，属肾性尿崩症，由V2受体合成减少或结构异常所致。"},{"q":"6岁女童，不慎从滑梯跌落摔伤，右下肢皮肤大面积破损。治疗修复期间，除注意补充蛋白质等营养物质外，还需注意补充","o":["维生素C和锌","维生素C和维生素B","铁和锌","维生素D和钙","维生素A和维生素C"],"a":0,"e":"胶原前肽的羟化需维生素C参与，锌是多种氧化酶的成分，二者缺乏均使肉芽组织及胶原形成不良，故创伤修复期应补充维生素C和锌。"},{"q":"一患者严重低钾血症，血钾浓度为2、5mol/L，导致呼吸肌麻痹，出现呼吸困难。治疗上除了常规补钾外，还需要进行给氧治疗。给氧原则是","o":["间歇性低浓度吸氧","慢速高浓度给氧","正压低浓度给氧","持续性低浓度低流量给氧","持续高浓度高流量给氧"],"a":3,"e":"呼吸肌麻痹致通气不足并伴CO2潴留时，呼吸中枢对CO2敏感性降低，靠低氧刺激维持呼吸，故须持续低浓度低流量给氧，高浓度吸氧可抑制呼吸。"},{"q":"患者，女，23岁。急诊收入院。寒战，高热，铁锈色痰。查体：体温39、8℃，左肺闻及湿啰音，X线胸片显示：左肺下叶大片状致密阴影。给予抗生素治疗，2天后症状减轻。该患者最可能患的疾病是","o":["大叶性肺炎","小叶性肺炎","病毒性肺炎","慢性支气管炎","肺脓肿"],"a":0,"e":"青壮年急起寒战高热、咳铁锈色痰，影像呈肺叶大片致密影，为肺炎链球菌引起的肺泡内纤维蛋白性炎，即大叶性肺炎。"},{"q":"某患者的血气检查结果：动脉血氧分压100mmHg（正常为100mmHg），血氧容量12ml/dl（正常值为20ml/dl），动脉血氧含量11.4ml/dl（正常值为19ml/dl），动-静脉血氧含量差3.5ml/dl(正常值为5ml/dl)，患者为哪种疾病的可能性比较大","o":["慢性支气管炎","急性呼吸窘迫综合征","慢性阻塞性肺疾病","慢性充血性心力衰竭","慢性贫血"],"a":4,"e":"动脉血氧分压正常而血氧容量和血氧含量均降低、动静脉氧差缩小，说明血液携氧能力不足而组织摄氧正常，符合贫血性缺氧。"},{"q":"患儿，4个月，因抽搐入院，患儿近两天发热抽搐，一天4～5次，抽搐后吃奶好。体检，体温38℃，发育营养好，精神好，咽充血，有颅骨软化，枕秃明显，前囟平。实验室检查：血清总钙1.7mmol/L，离子钙1.0mmol/L。该患儿可能出现的电解质紊乱是","o":["低磷血症","高钙血症","高钠血症","高镁血症","低钙血症"],"a":4,"e":"血清总钙1.7mmol/L、离子钙1.0mmol/L均低于正常，结合颅骨软化、枕秃及抽搐，为低钙血症致神经肌肉应激性增高。"},{"q":"手术中见肝有一肿物，无明显境界，颜色暗红，切开可见肿物呈囊状，其间有许多红褐色液体流出，镜检见多量管腔，管壁厚薄不均并扩张迂曲，管腔内有多量红细胞。此瘤可诊断为","o":["肝癌","肝血管瘤","肝腺瘤","肝淋巴管瘤","肝囊状水瘤"],"a":1,"e":"肿物由扩张迂曲、管壁厚薄不均的血腔构成，腔内充满红细胞，切面呈海绵状并流出红褐色液体，为肝海绵状血管瘤。"},{"q":"患者，女，30岁。右卵巢肿物6cm×5cm，切面囊实性，可见油脂样物及毛发。镜下见成熟表皮、毛囊和皮脂腺结构，还见到支气管柱状上皮、纤维脂肪组织等，此肿瘤诊断为","o":["成熟型畸胎瘤","未成熟型畸胎瘤","卵巢癌","毛发上皮瘤","混合瘤"],"a":0,"e":"囊内充满皮脂样物及毛发，镜下见成熟表皮、毛囊、皮脂腺和支气管上皮等多种成熟组织，由多个胚层构成，符合成熟型畸胎瘤。"},{"q":"患者，男，20岁。高热4天，咳铁锈色痰，查体左肺上部叩诊浊音，呼吸音弱，其胸片表现最大可能是","o":["左上肺纹理增粗","双肺散在片絮状阴影","左上肺淡薄片状模糊阴影","左上肺大片状均匀致密阴影","左上肺淡薄不均阴影，可见少许透亮区"],"a":3,"e":"大叶性肺炎实变期肺泡腔内充满纤维蛋白和红细胞，病变累及整个肺叶，X线呈大片均匀致密阴影，与叩诊浊音、呼吸音减弱相一致。"},{"q":"患者，女，23岁。因心悸气短、夜间无法平卧2月，发热1周入院。10年前被诊断为“风湿热”，未系统治疗。查体：睑结膜有瘀点，在大拇趾尖端掌面有一紫红色结节，有压痛。体温38、0℃，脉搏120次/分，主动脉听诊区可闻及舒张期叹气样杂音。尿常规：少量蛋白。血常规：WBC 9.9×109/L，中性粒细胞0.84，淋巴细胞0.16、最可能的诊断是","o":["上呼吸道感染","急性肾小球肾炎","风湿热","亚急性感染性心内膜炎","主动脉瓣关闭不全"],"a":3,"e":"风湿热病史伴发热、睑结膜瘀点、指端痛性结节及主动脉瓣舒张期杂音，为亚急性感染性心内膜炎，赘生物脱落可引起周围动脉栓塞。"},{"q":"患儿，女，12岁。近5个月来反复发热，大关节出现游走性红、肿、痛，同时患儿有乏力，不爱活动，稍活动后即有心跳加快。入院检查，诊断为风湿性心肌炎，风湿性关节炎。此种关节炎关节腔可见到的病变是","o":["化脓性炎","坏死性炎","浆液纤维素性炎","假膜性炎","肉芽肿性炎"],"a":2,"e":"风湿性关节炎属变态反应性炎症，关节腔渗出以浆液和纤维蛋白为主，为浆液纤维素性炎；炎症消退后关节功能多完全恢复，不化脓。"},{"q":"患者，男，45岁。体格检查时发现结肠肠腔内有一带蒂赘生物，活检组织送病理科检查，镜下显示主要为增生的肠黏膜上皮腺体细胞和少量肉芽组织，最可能的诊断是","o":["炎性假瘤","炎性息肉","炎性肉芽肿","息肉状腺瘤","黏膜淋巴瘤"],"a":1,"e":"息肉由增生的黏膜腺上皮与少量肉芽组织构成，是慢性炎症刺激下黏膜增生及修复的结果，属炎性息肉而非真性肿瘤。"},{"q":"患者，女，18岁，食欲不好，厌油腻，肝大，肝区疼痛，临床诊断为急性普通性肝炎，此时患者肝出现的病变为","o":["以实质变质为主","以间质变质为主","以浆液渗出为主","以中性粒细胞渗出为主","以纤维素渗出为主"],"a":0,"e":"急性普通型肝炎以肝细胞变性、坏死为主，间质反应轻微，属变质性炎；坏死多呈点状，汇管区仅见少量炎症细胞浸润。"},{"q":"患者，男，36岁。反复咳嗽，咳痰，体温38、5度，WBC：12×109/L（正常值4～10×109/L），X线胸片显示在右肺下叶有大片致密阴影。抗病毒治疗无效。该患者最有可能的诊断是","o":["大叶性肺炎","小叶性肺炎","病毒性肺炎","慢性支气管炎","肺结核"],"a":0,"e":"青壮年高热、白细胞升高、肺叶大片致密影且抗病毒治疗无效，符合肺炎链球菌所致大叶性肺炎；病毒性肺炎多为间质性且白细胞不升高。"},{"q":"患者，女，50岁。患慢性萎缩性胃炎20余年，现因胃癌行胃大部切除术。手术切除标本显示整个胃腔缩小，胃壁增厚变硬，呈“革囊胃”。该患者胃癌的大体形态类型属于","o":["浸润型","息肉型","溃疡型","胶样癌","隆起型"],"a":0,"e":"癌组织在胃壁内弥漫浸润，使胃壁普遍增厚变硬、胃腔缩小，形成“革囊胃”，属浸润型胃癌；该型镜下多为低分化腺癌或印戒细胞癌。"},{"q":"某患儿因窒息急诊入院，血气分析为：pH 7.19，标准条件下测得HCO3-的浓度为24mmol/L，隔绝空气的条件下测得HCO3-的浓度为30mmol/L，该患儿最可能出现的酸碱平衡紊乱是","o":["代谢性酸中毒","急性呼吸性酸中毒","急性呼吸性碱中毒","慢性呼吸性酸中毒","混合性酸碱平衡紊乱"],"a":1,"e":"窒息致CO2急性潴留，隔绝空气测得的HCO3-高于标准条件测定值，说明急性期HCO3-代偿性升高有限，结合pH明显下降，为急性呼吸性酸中毒。"},{"q":"患者，女，35岁。近段时间病人食欲不振，腹胀，右腹部疼痛不适 。查体：肋缘下2cm触及肝脏，按压有疼痛。未明确诊断，应首先做下列哪项检查","o":["肝炎病毒标记物","腹水检查","胃肠钡餐造影","超声心动图","腹部B超"],"a":0,"e":"纳差、腹胀、肝区痛伴肝大压痛提示肝脏炎症性病变，首先应检测肝炎病毒标记物以明确病原与类型，影像学检查随后用于形态评估。"},{"q":"患者，男，68岁。反复咳嗽、咳痰20年，伴心悸2年。体检：双肺叩诊呈过清音，呼吸音减弱，肺底部有湿啰音，剑突下心尖搏动明显，该处可闻及3/6级收缩期杂音，肺动脉瓣区第二音亢进。该例最可能的诊断为","o":["慢性支气管炎","慢支+肺气肿","慢支+肺气肿+肺心病","慢支+风湿性心瓣膜病","慢支+右心功能不全"],"a":2,"e":"长期咳嗽咳痰、桶状胸及过清音提示慢支合并肺气肿；剑突下心脏搏动、肺动脉瓣第二心音亢进说明已累及右心，形成肺心病。"},{"q":"患者，女，50岁。近3年来，活动后出现胸痛，常放射至左肩，左臂内侧，每次发作含硝酸甘油后缓解。近半年来，疼痛加剧、发作频繁。今日清晨患者上楼后胸痛发作，持续30分钟未见缓解，大汗、面色苍白，可能诊断为","o":["心绞痛","心肌梗死","左心衰竭","心内膜炎","心外膜炎"],"a":1,"e":"胸痛持续30分钟以上、含服硝酸甘油不缓解并伴大汗、面色苍白，提示冠状动脉供血中断致心肌坏死，为急性心肌梗死。"},{"q":"患者，女，25岁。患风湿病5年。听诊可闻及心包摩擦音。心包腔内渗出物的特征性成分应该是","o":["淋巴细胞","纤维素","中性粒细胞","巨噬细胞","红细胞"],"a":1,"e":"风湿性心包炎为浆液纤维素性炎，纤维蛋白沉积于脏、壁层心包之间，随心脏搏动相互摩擦产生心包摩擦音，故渗出物的特征成分为纤维素。"},{"q":"患者，男，10岁，腹痛2天，伴有发热，呕吐。初始疼痛部位不确定，后疼痛逐渐集中于右下腹，体温38.5℃。医生诊断为急性蜂窝织炎性阑尾炎，决定立即手术。切除的阑尾送病理科检验，镜下检查以哪种细胞为主","o":["淋巴细胞","巨噬细胞","嗜酸性粒细胞","中性粒细胞","浆细胞"],"a":3,"e":"急性蜂窝织炎性阑尾炎属化脓性炎，大量中性粒细胞弥漫浸润阑尾各层并伴脓性渗出；以淋巴细胞为主者见于慢性炎症。"},{"q":"患者，男，60岁。长期以来感觉上腹胀，食欲不振，近3个月体重明显减轻。胃镜检查显示：胃窦部位黏膜变薄，颜色灰暗，病变黏膜下血管清晰可见。周围正常黏膜隆起。最可能的诊断为","o":["慢性浅表性胃炎","慢性萎缩性胃炎","急性刺激性胃炎","胃溃疡","早期胃癌"],"a":1,"e":"胃黏膜变薄、色泽灰暗、黏膜下血管透见，为黏膜萎缩的表现，符合慢性萎缩性胃炎；该型常伴肠上皮化生，属癌前状态。"},{"q":"男性患者，肝炎肝硬化病史20余年，查体：轻度脱水，上腹部膨隆，有移动性浊音。该症状的发生与下列哪项无关","o":["门脉高压","血浆胶体渗透压下降","醛固酮增多","ADH增多","肾小球滤过率增加"],"a":4,"e":"腹水由门脉高压、低白蛋白致胶体渗透压下降以及醛固酮、ADH增多引起水钠潴留共同所致；肾小球滤过率增加反而促水排出，与腹水无关。"},{"q":"自由基中能使染色体发生畸变主要是","o":["O2-","1O2","OH•","LO•","LOO•"],"a":2,"e":"羟自由基化学性质最活泼，可直接攻击DNA，引起碱基修饰、链断裂和染色体畸变；超氧自由基多经衍生为羟自由基而间接造成损伤。"},{"q":"一患者发生呼吸困难，检测肺泡通气血流比例大于0.8，提示患者可能出现","o":["肺不张","肺动脉栓塞","肺水肿","支气管肺炎","慢性阻塞性肺疾病"],"a":1,"e":"肺泡通气正常而血流减少，使通气血流比例大于0.8，形成无效腔样通气，见于肺动脉栓塞；肺不张、肺水肿时该比值则降低。"},{"q":"一患者因慢性心瓣膜病而入院，如其血气分析结果为PaCO2 升高，同时HCO3－降低，最可能的诊断是","o":["呼吸性酸中毒","代谢性酸中毒","呼吸性碱中毒","代谢性碱中毒","混合型酸碱平衡紊乱"],"a":4,"e":"PaCO2升高提示肺泡通气不足，HCO3-降低提示代谢性酸中毒，二者并存且pH明显偏移，属混合型酸碱平衡紊乱。"},{"q":"患者，男，60岁。严重水肿、大量蛋白尿、低蛋白血症、高脂血症，其最可能患有的原发性肾小球肾炎类型是","o":["急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","IgA肾病","微小病变性肾小球病","膜性肾小球病"],"a":4,"e":"成人肾病综合征最常见的原因是膜性肾小球病，其基膜上皮侧免疫复合物沉积使基膜弥漫增厚，临床出现大量蛋白尿、重度水肿、低蛋白血症和高脂血症。"},{"q":"患者，男，38岁。因发热2个月而入院。该患者2个月来不规则发热，伴体重减轻，右上腹部疼痛，呼吸时加重，有时伴咳嗽、胸痛，体检时肝区有明显压痛和叩击痛。X线检查：右侧膈肌抬高，活动受限，伴有少量胸腔积液。肝穿刺获得典型的黄色脓液。既往有慢性腹泻病史。该患者应首先考虑","o":["阿米巴肝脓肿","肠阿米巴穿孔","阿米巴肺脓肿","阿米巴肾脓肿","结核性胸膜炎"],"a":0,"e":"不规则发热、右上腹痛及肝大压痛，肝穿刺抽得脓液，结合慢性腹泻史，为溶组织内阿米巴经门静脉入肝形成的阿米巴肝脓肿。"},{"q":"患者，男，64岁。患高血压病10年。近日有夜间憋醒、气促伴咳嗽、气喘，在考虑心源性哮喘与支气管哮喘的鉴别时，下列哪项有助于心源性哮喘的诊断","o":["肝肿大伴下肢水肿","心率超过120次/分","双肺底湿啰音","心脏向左扩大","咳嗽咳痰"],"a":3,"e":"心源性哮喘由急性左心衰竭肺淤血引起，多有高血压、冠心病史及心脏扩大等器质性心脏病证据；支气管哮喘者心脏大小正常。"},{"q":"患者，男性，60岁，急性心力衰竭并发支气管肺炎入院，血气测定结果如下：pH：7.17，PaCO2：48mmHg，HCO3ˉ：17mmol/L，Na+：140mmol/L，Cl－：104mmol/L，K+：4.5mmol/L，最可能的酸碱平衡紊乱类型是","o":["AG正常型代谢性酸中毒","AG增高型代谢性酸中毒","代谢性酸中毒合并代谢性碱中毒","AG增高型代谢性酸中毒合并呼吸性酸中毒","呼吸性酸中毒合并呼吸性碱中毒"],"a":3,"e":"AG=140-104-17=19mmol/L，为AG增高型代谢性酸中毒；PaCO2 48mmHg高于代偿预期，提示同时存在呼吸性酸中毒，故二者合并。"},{"q":"患者，女，43岁。诊断为二尖瓣狭窄，患者可能出现的临床表现中不包括","o":["呼吸困难","咳粉红色泡沫状痰","颈静脉怒张","水冲脉","心尖区舒张期隆隆样杂音"],"a":3,"e":"二尖瓣狭窄使左房压升高、肺淤血，出现呼吸困难和粉红色泡沫痰，晚期右心受累致颈静脉怒张；水冲脉见于主动脉瓣关闭不全，故不出现。"},{"q":"患儿，女，足月顺产，牛奶喂养。13天后出现烦躁不安，易激怒，四肢肌张力增高，腱反射增强，血钙1、6mmol/L，血糖5、8mmol/L，最有可能的诊断是","o":["新生儿低血糖","新生儿低血钙","新生儿缺氧缺血性脑病","新生儿颅内出血","新生儿破伤风"],"a":1,"e":"牛奶含磷高、钙磷比例不当，使血钙降低；低钙导致神经肌肉应激性增高，出现烦躁、肌张力增高和腱反射增强，故为新生儿低血钙。"},{"q":"男性，35岁。右下腹痛、腹泻5天伴低热。大便呈酱色、腥臭。粪便检查：红细胞（++），白细胞（+），查见阿米巴滋养体及包囊。请问该患者何种疾病","o":["阿米巴痢疾","细菌性痢疾","血吸虫病","阿米巴肿","阿米巴肝脓肿"],"a":0,"e":"大便呈暗红色果酱样、有腥臭，镜检见阿米巴滋养体及包囊，病变位于盲肠和升结肠，为溶组织内阿米巴所致的肠阿米巴病。"},{"q":"患儿，男，7岁。因发热、头痛，呕吐呈喷射状1天入院。T：39.5℃，P：155次/分，R：30/分，BP：90/50mmHg，烦躁不安，意识朦胧，呼吸困难，肝肋下7cm，手臂、胸、腹及下肢等处出现红色、紫红色瘀点和瘀斑。白细胞总数15、0×109/L ，中性粒细胞0.78；红细胞3.59×1012/L，血红蛋白85g/L。凝血酶原时间18秒 (正常11～14秒) 。积极抢救无效死亡。入院时该患儿最可能的诊断是：","o":["暴发性脑脊髓膜炎并发沃-弗综合征","过敏性紫癜","流行性乙型脑炎","病毒性肝炎","心力衰竭"],"a":0,"e":"暴发型流脑败血症短期内出现广泛瘀点瘀斑、休克和DIC，伴肾上腺出血及功能衰竭，称沃-弗综合征；脑膜炎症病变反而较轻。"},{"q":"患者，女，27岁。阑尾炎手术后、刀口对合严密整齐、无感染，一般术后多久拆线","o":["术后3天","术后1周","术后2周","术后3周","术后4周"],"a":1,"e":"一期愈合见于组织缺损少、创缘整齐、无感染的伤口，阑尾手术切口即属此类，上皮24～48小时覆盖，约1周胶原形成足够强度即可拆线。"},{"q":"患者，男，50岁。因肾结石、尿路阻塞就诊。超声检查发现肾体积增大，肾实质变薄。这种病理改变称为","o":["肥大","变性","萎缩","发育不良","化生"],"a":2,"e":"尿路梗阻致肾盂积水，肾组织长期受压而萎缩变薄，属压迫性萎缩；肾体积增大由积水所致，实质减少才是萎缩的本质。"},{"q":"患者，男，68岁。反复咳嗽、咳痰10余年，近两年来咳嗽、咳痰加重，并出现呼吸气促，呈渐进加重。査体：桶状胸，语颤减弱，叩诊呈过清音，心浊音界缩小，肺下界下移，两肺呼吸音减弱，本病例最可能的诊断是","o":["慢性支气管炎急性发作","慢性阻塞性肺气肿","慢性支气管炎并发阻塞性肺气肿","慢性支气管哮喘","自发性气胸"],"a":2,"e":"长期咳嗽咳痰后出现渐进性气促、桶状胸、过清音和肺下界下移，为慢性支气管炎并发阻塞性肺气肿；单纯慢支无肺气肿体征。"},{"q":"一女性患者，甲状腺肿大前来就医。手术切除标本镜下检查，见甲状腺滤泡灶性坏死、坏死滤泡的胶质外溢，较多异物巨细胞增生形成肉芽肿。自述曾有病毒感染史。该患者可能患有","o":["亚急性甲状腺炎","慢性淋巴细胞性甲状腺炎","桥本甲状腺炎","结节性甲状腺炎","甲状腺腺瘤"],"a":0,"e":"甲状腺滤泡灶性坏死、胶质外溢并见异物巨细胞构成肉芽肿，结合病毒感染史，为亚急性肉芽肿性甲状腺炎。"},{"q":"某患者有畏寒、发热、腹痛、腹泻、脓血便和里急后重，应考虑为","o":["细菌性痢疾","肠阿米巴病","食物中毒","肠伤寒","急性肠炎"],"a":0,"e":"畏寒发热、腹痛腹泻伴脓血便和里急后重，为志贺菌侵犯结肠黏膜形成假膜性炎的典型表现，即急性细菌性痢疾。"},{"q":"某38岁男性游客到玉龙雪山旅游，登山至海拔4000米左右时，呼吸困难加重，咳粉红色泡沫痰，皮肤发绀，该游客可能出现的病理变化是","o":["高原性肺水肿","急性心力衰竭","过敏性休克","下肢深静脉血栓","高原性代偿反应"],"a":0,"e":"高原低氧使肺毛细血管通透性增高，血浆渗入肺泡，出现呼吸困难、粉红色泡沫痰和发绀，为高原性肺水肿。"},{"q":"患者，男，48岁。肝硬化腹水严重入院治疗，由于短时间内抽取腹水过多，患者突发晕厥。其晕厥的原因是","o":["腹腔内动脉炎症性充血","腹腔内静脉炎症性充血","腹腔内动脉减压后充血","脑动脉减压后充血","脑动脉炎症性充血"],"a":2,"e":"大量腹水长期压迫腹腔器官，抽液后局部压力骤降，细动脉反射性扩张而充血，血液淤积于腹腔，回心血量和脑供血减少而晕厥。"},{"q":"患者，女，31岁，孕40周。分娩时出现寒战及呼吸困难，阴道大量流血，注射催产素后仍流血不止。测血压60/40mmHg，血红蛋白70g/L，血小板计数90×109/L，凝血酶原时间22秒（正常11～14秒），3P试验阳性，D-二聚体阳性。此时该患者处于DIC哪一期","o":["高凝期","低凝期","消耗性低凝期","原发性纤溶亢进期","继发性纤溶亢进期"],"a":4,"e":"DIC晚期凝血因子和血小板大量消耗，继发纤溶亢进，3P试验及D-二聚体阳性、凝血酶原时间延长、出血不止，符合继发性纤溶亢进期。"},{"q":"患者，男68岁，20年前被诊断为慢性支气管炎，未系统治疗。今冬12月，咳、痰、喘加重，门诊以“肺气肿”收住入院。患者用力呼气时，呼吸困难明显加重。肺功能检查发现呼气时出现小气道闭合，其发生机制主要是","o":["小气道管壁增厚","小气道阻塞","小气道痉挛","气道等压点移至膜性气道","小气道顺应性降低"],"a":3,"e":"肺气肿时肺泡弹性回缩力下降，呼气时气道内压迅速降至胸内压以下，等压点向膜性小气道移动，致呼气时气道闭合、气体滞留。"},{"q":"患者，男，60岁。身体消瘦。最近感觉腹部胀满，食欲不振就诊。平时平均每天抽一包烟。胃镜检查显示：胃窦部位黏膜变薄，颜色灰暗。病理检查发现肠上皮化生。诊断为","o":["早期胃癌","胃溃疡","慢性浅表性胃炎","慢性萎缩性胃炎","神经官能症"],"a":3,"e":"胃窦黏膜变薄、色泽灰暗并见肠上皮化生，符合慢性萎缩性胃炎；腺体减少和化生是其与浅表性胃炎鉴别的关键。"},{"q":"患者，女，45岁。急腹症入院。B超示腹部有一个5cm×7cm×8cm的肿物。术后病理检查发现：送检组织为卵巢肿物，切开内有大量浆液流出，囊壁上有一乳头状肿物向腔内生长，镜下未见异型性明显的细胞。该患者的病理诊断是","o":["脂肪瘤","平滑肌瘤","淋巴管瘤","囊腺瘤","管状腺瘤"],"a":3,"e":"囊性肿物内含清亮液体，囊壁见乳头状突起而细胞无明显异型性，为卵巢浆液性囊腺瘤；乳头无间质浸润、细胞无异型是与癌鉴别的要点。"},{"q":"患者，女，26岁。因急腹症致感染性休克入院。现患者情况进一步恶化，血压进行性下降，神志淡漠，少尿，皮肤发绀。此时患者可能处于","o":["休克难治期","休克早期","休克期","代偿期","临终期"],"a":2,"e":"休克期微循环淤血、回心血量减少，血压进行性下降，出现神志淡漠、少尿和皮肤发绀；休克早期血压尚可代偿维持。"},{"q":"患者，男，55岁。高血压病史已20余年。手术切除脾脏，切片可见脾小体中央动脉管壁增厚，管腔狭窄，管壁内可见均匀红染、半透明物质。这些半透明物质为","o":["淀粉样物质","血浆蛋白和基膜样物质","胶原纤维","免疫球蛋白","脂蛋白"],"a":1,"e":"高血压时细动脉内皮受损，血浆蛋白渗入管壁并与基膜样物质沉积，形成红染均质的玻璃样变，使管壁增厚、管腔狭窄。"},{"q":"一严重肝病患者出现精神错乱，意识不清、睡眠障碍等症状，查血见血氨水平明显升高。下列可用于降低血氨的治疗方式是","o":["吸氧","镇静类药物","口服左旋多巴","静脉输支链氨基酸溶液","口服乳果糖"],"a":4,"e":"乳果糖在结肠被细菌分解为有机酸，酸化肠腔，使氨转化为铵离子随粪便排出，并减少氨的吸收，故可降低血氨。"},{"q":"一休克患者，已出现血压进行性下降，皮肤出现花斑，伴有少尿、无尿。此时病人的肾障碍属于","o":["肾前性、功能性","肾性、功能性","肾后性、功能性","肾性、器质性","肾后性、器质性"],"a":3,"e":"休克持续使肾血流量锐减，肾小管缺血缺氧发生坏死，出现少尿、无尿及氮质血症，属器质性肾损伤，即肾性、器质性肾功能障碍。"},{"q":"盛暑行军时大量饮纯净水可能会发生","o":["水中毒","等渗性脱水","低渗性脱水","高渗性脱水","水肿"],"a":2,"e":"盛暑行军大量出汗丢失水和钠，仅饮纯净水只补充水分而未补钠，细胞外液渗透压降低，故发生低渗性脱水。"},{"q":"患者，女，55岁，绝经后阴道流血1月余。妇科检查：宫颈光滑，宫体正常大，附件(-)，宫颈细胞学检查未见异常。首先应怀疑的疾病是","o":["子宫肌瘤","子宫腺肌病","子宫颈炎","子宫内膜异位症","子宫内膜癌"],"a":4,"e":"绝经后阴道流血而宫颈光滑、细胞学检查阴性，病变应位于子宫体内膜，首先考虑子宫内膜癌，需行分段诊刮确诊。"},{"q":"患者，男，20岁，高热4天，咳铁锈色痰，查体左肺上部叩诊实变，临床诊断为大叶性肺炎，该病变性质为","o":["浆液性炎","增生性炎","变质性炎","假膜性炎","纤维素性炎"],"a":4,"e":"大叶性肺炎的本质是肺泡内纤维蛋白渗出，属纤维素性炎；纤维素网使肺组织实变，并因红细胞破坏而咳铁锈色痰。"},{"q":"患者，女性，20岁，阑尾切除术后，残留在体内的缝线周围可能出现的病理改变是","o":["化脓性炎","肉芽肿性炎","炎性假瘤","机化","蜂窝织炎"],"a":1,"e":"缝线为不能被消化的异物，长期存留刺激巨噬细胞增生并融合成异物巨细胞，周围有纤维组织包绕，属异物性肉芽肿性炎。"},{"q":"患者，女，18岁。分别在肛周3点、5点、8点和11点处有4个黄豆至红枣大小不等的增生物，色淡红，质软，呈菜花状、乳头状，表面凸凹不平，表面有溃破，覆有脓性分泌物。镜检可见表皮浅层有凹空细胞。考虑诊断为","o":["淋病","梅毒","湿疹","尖锐湿疣","扁平湿疣"],"a":3,"e":"外阴菜花状、乳头状增生物，镜下见表皮浅层凹空细胞，为人乳头状瘤病毒（HPV-6、11型）感染所致的尖锐湿疣。"},{"q":"患者，女，25岁。反复出现皮肤、肾、关节、心、浆膜等组织损害，血清检测抗DNA抗体阳性，临床诊断为系统性红斑狼疮。该病最具病理诊断价值的是","o":["面部蝶形红斑","肾损害","非细菌性疣赘性心内膜炎","关节受累","狼疮小体"],"a":4,"e":"抗核抗体与受损细胞核结合后使核肿胀并被挤出胞体，形成狼疮小体（苏木素小体），对SLE有明确诊断意义，是最具诊断价值的病变。"},{"q":"一患者氧动脉血氧分压为50mmHg，动脉二氧化碳分压为70mmHg，导致此现象发生的最可能是","o":["呼吸膜厚度增加","肺泡通气血流比例失调","肺泡膜面积减少","肺循环动静脉短路增加","肺泡扩张的弹性阻力增加"],"a":4,"e":"PaO2降低伴PaCO2明显升高，说明存在肺泡通气不足；肺弹性阻力增加使通气动力受限、肺泡通气量下降，是唯一能引起CO2潴留的选项。"},{"q":"一患者因急性肾衰竭入院，查尿量为250ml/24h。该患者此时可能出现的最严重并发症是","o":["水中毒","高钾血症","代谢性酸中毒","氮质血症","肾性高血压"],"a":1,"e":"少尿期尿量仅250ml/24h，钾排出受阻而组织分解增强，血钾迅速升高，可致心律失常甚至心搏骤停，故最严重的并发症是高钾血症。"},{"q":"患者，男，15岁。近1年来经常出现鼻塞。检查发现右鼻道内有一赘生物，遂行赘生物切除术。病理检查结果显示：鼻黏膜上皮增生，皮下结缔组织高度水肿，较多淋巴细胞和浆细胞浸润。该赘生物可诊断为","o":["鼻炎性息肉","鼻炎性假瘤","鼻良性肿瘤","鼻恶性肿瘤","鼻肉芽肿性炎症"],"a":0,"e":"鼻黏膜上皮增生伴间质高度水肿、大量淋巴细胞和浆细胞浸润，为慢性炎症刺激下黏膜增生形成的炎性息肉，即鼻息肉。"},{"q":"男性，60岁，最初有皮肤病损，皮肤组织活检见Pautrier微脓肿 ，肿瘤细胞体积较大，核扭曲，该患者可能患有","o":["滤泡性淋巴瘤","弥漫性大B细胞性淋巴瘤","淋巴母细胞性淋巴瘤","Burkitt淋巴瘤","蕈样肉芽肿"],"a":4,"e":"瘤细胞核高度扭曲、呈脑回状，并侵入表皮聚集成Pautrier微脓肿，为原发于皮肤的成熟T细胞淋巴瘤，即蕈样肉芽肿。"},{"q":"患者，女，30岁。腰椎结核并在背部形成冷脓肿，冷脓肿向表皮溃破。破溃处流脓不断。此现象称为","o":["坏死组织溶解吸收","坏死组织机化","坏死组织包裹钙化","坏死组织分离排出","坏死组织恶变"],"a":3,"e":"结核性冷脓肿向体表溃破后，坏死物液化并不断经破口排出，属坏死组织的分离排出，局部可形成溃疡或窦道。"},{"q":"女性，45岁，高血压病史15年，并有高血压家族史。近半年来经常出现气喘、心悸，劳动后加重。查体：肥胖体型，血压170/100mmHg，X线检查，心脏增大。患者心脏可能出现的病变是","o":["左心室肥大","心肌萎缩","心肌纤维化","心肌梗死","心肌炎"],"a":0,"e":"长期高血压使左心室压力负荷增加，心肌细胞代偿性肥大、室壁增厚，形成向心性肥大；失代偿后心腔扩张。"},{"q":"患者，男，70岁。咳嗽，痰中带血半年来院检查。既往体健，吸烟45年。X线示右肺门处见一个7cm×6cm巨大不规则阴影，边界不清，其最可能诊断是","o":["肺鳞癌","肺脓肿","肺炎性假瘤","肺结核","肺内转移癌"],"a":0,"e":"老年重度吸烟者，肺门部巨大不规则肿块伴痰中带血，符合中央型肺癌，其组织学类型以鳞状细胞癌最多见。"},{"q":"患者，男，53岁。反复腹泻、便秘交替出现9年，加重伴腹胀3个月。既往史，每周饮白酒50～100ml(1～2两)15年，务农。查体：消瘦，皮肤巩膜无黄染，腹隆，肝在剑突下4cm，脾下缘平脐，移动性浊音（+）。结肠镜检查病变黏膜苍白、萎缩，有许多呈密集分布、数毫米大小、平坦或稍隆起的黄色结节及虫卵性息肉。B超提示肝硬化。该患者考虑诊断为","o":["门脉性肝硬化","胆汁性肝硬化","酒精性肝硬化","血吸虫性肝硬化","心源性肝硬化"],"a":3,"e":"长期疫水接触、结肠虫卵性息肉及脾大、腹水，提示血吸虫虫卵在门管区沉积引起纤维化，形成血吸虫性肝硬化（肝纤维化）。"},{"q":"一男性患者，有多年慢性肝病史，体检时发现四肢和躯干多处蜘蛛痣，手掌发红，出现上述表现的主要原因是","o":["胰高血糖素灭活减少","醛固酮灭活减少","ADH灭活减少","胰岛素灭活减少","雌激素灭活减少"],"a":4,"e":"肝硬化时肝脏对雌激素灭活减少，血中雌激素升高，使小动脉末端分支扩张形成蜘蛛痣，手掌大、小鱼际发红即肝掌。"},{"q":"某患者消化道手术后禁食3天，仅静脉输入大量5%葡萄糖液，此患者最容易发生的电解质紊乱是","o":["低钠血症","低钙血症","低镁血症","低磷血症","低钾血症"],"a":4,"e":"禁食3天仅输5%葡萄糖而无需补钾，葡萄糖刺激胰岛素分泌促使钾进入细胞，加之组织分解消耗钾，故易发生低钾血症。"},{"q":"患者，男，56岁。患高血压病13年，其血管壁玻璃样变多见于","o":["大动脉","中型动脉","细动脉","大静脉","小静脉"],"a":2,"e":"高血压时细动脉长期痉挛、内皮通透性增高，血浆蛋白渗入管壁形成玻璃样变，是其最基本的血管病变，多见于肾入球动脉和脾中央动脉。"},{"q":"患儿，女，8岁。因呕吐、腹泻1天到当地医院就诊，给予静脉点滴葡萄糖500ml，回家后病情无好转，出现发热、烦躁、少尿，来我院就诊，查血清钠155mmol/L，该患者出现的水、钠代谢紊乱是","o":["高渗性脱水","等渗性脱水","低渗性脱水","水中毒","水肿"],"a":0,"e":"腹泻丢失低渗液后仅补葡萄糖，失水多于失钠，血清钠155mmol/L、血浆渗透压升高，为高渗性脱水，故有发热、烦躁和少尿。"},{"q":"患者，男，65岁。患慢性阻塞性肺气肿8年。近日因受凉感冒后出现活动时心悸、气短，下肢水肿，腹胀。查体：肝颈静脉反流征阳性，肝肋缘下3cm，双下肢凹陷性水肿。临床诊断：慢性肺源性心脏病。缓解该患者肺心病症状最有效的办法是","o":["降低右心前负荷","降低右心后负荷","降低左心前负荷","降低左心后负荷","增强心肌收缩力"],"a":1,"e":"肺心病时肺循环阻力增高使右心室后负荷加重，是右心衰竭的根本环节，故降低肺动脉压、减轻右心后负荷最能缓解症状。"},{"q":"患儿，男，8岁。近1个月来出现显著的面部和下肢水肿，低蛋白血症，高脂血症，大量蛋白尿和脂尿，未发现血尿。此前没有其他病史。其最可能患有的原发性肾小球疾病是","o":["急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","微小病变性肾病","IgA肾病","膜性肾小球病"],"a":2,"e":"儿童肾病综合征、大量蛋白尿伴脂尿而无血尿，光镜下肾小球基本正常，电镜见足突弥漫融合，为微小病变性肾病，对糖皮质激素敏感。"},{"q":"患者，男，45岁。鼻塞、涕中带血半年余，近1个月发现右侧胸锁乳突肌上段前缘出现无痛性肿块。应首先考虑下列哪种疾病","o":["淋巴瘤","淋巴结结核","鼻咽癌颈部淋巴结转移","淋巴结反应性增生","肺癌颈部淋巴结转移"],"a":2,"e":"鼻塞、涕中带血伴颈上部无痛性肿块，为鼻咽癌常见的首发表现；癌组织黏膜下浸润，早期即经咽后淋巴结转移至颈深上淋巴结。"},{"q":"患者，男，55岁。有长期酗酒史，每日饮白酒量超过100ml。最近B超显示，肝脏体积缩小，脾脏肿大。患者可能的诊断是","o":["门脉性肝硬化","坏死后肝硬化","血吸虫性肝硬化","淤血性肝硬化","胆汁性肝硬化"],"a":0,"e":"长期大量饮酒引起酒精性肝炎、肝细胞坏死及纤维化，形成小结节型（门脉性）肝硬化，表现为肝体积缩小、门脉高压和脾大。"},{"q":"一ARF患者，尿量为750ml/天，伴进行性氮质血症及代谢性酸中毒，无高钾血症。该患者此时可能处于的病程是","o":["少尿型ARF少尿期","少尿型ARF多尿期","少尿型ARF移行期","少尿型ARF恢复期","非少尿型ARF"],"a":4,"e":"24小时尿量750ml已超过少尿标准，但出现进行性氮质血症和代谢性酸中毒，符合非少尿型急性肾衰竭，其肾小管浓缩功能受损而尿量不减少。"},{"q":"患者，男，35岁。住院手术后出现肝功能异常 。据调查，患者术中输血500ml。为明确诊断，患者需要首先做何检查","o":["病原血清学检查","病理活检","B超","CT","MRI"],"a":0,"e":"术中输血后出现肝功能异常，应首先排除输血传播的乙型、丙型肝炎，故首选病原血清学检查，影像学检查仅作辅助评估。"},{"q":"某患者临床检查结果：①淋巴细胞DNA琼脂糖凝胶电泳谱：梯状条带。②淋巴细胞电镜检查：细胞皱缩，胞膜及细胞器相对完整，核固缩。③淋巴细胞核酸内切酶活性测定：显著增强。 请问患者淋巴细胞发生什么病理改变","o":["淋巴细胞浸润","淋巴细胞坏死","淋巴细胞凋亡","淋巴细胞分裂","淋巴细胞恶性变"],"a":2,"e":"DNA降解为180～200bp片段、电泳呈梯状带，细胞皱缩而胞膜及细胞器完整，核酸内切酶活性增强，均为凋亡的典型表现。"},{"q":"患者，男，36岁。四年前被诊断为梅毒，现皮肤、黏膜、骨、关节以及各内脏等多部位均受累及，并有特征性树胶样肿形成。有麻痹性痴呆表现。该患者的病程处于","o":["早期梅毒","后天性一期梅毒","后天性二期梅毒","后天性三期梅毒","先天性梅毒"],"a":3,"e":"感染后4～5年病变累及内脏，出现树胶样肿及麻痹性痴呆，属三期梅毒；一、二期为早期梅毒，以硬下疳和梅毒疹为主。"},{"q":"患者，女，73岁。大便性状改变月余，大便潜血阳性。经肠镜检查发现一个0、5cm×1、0cm的息肉。病理报告显示:横结肠黏膜腺癌，淋巴管内见癌栓。本患者之恶性肿瘤与下列哪个抑癌基因密切相关","o":["APC","WT-1","P16","NF-1","BRCA-2"],"a":0,"e":"结直肠癌发生中APC基因突变起始动作用，其失活使WNT通路持续激活、β联蛋白蓄积，细胞异常增殖；该基因胚系突变见于家族性腺瘤性息肉病。"},{"q":"患者，女，20岁。右乳外上象限有一直径约2.5cm大小的圆形肿块，边界清楚，表面光滑，可移动，不痛。此肿块最可能的是","o":["乳腺癌","乳腺纤维腺瘤","乳腺增生症","炎性包块","乳腺脓肿"],"a":1,"e":"青年女性、肿块圆形、边界清楚、表面光滑、活动度好，为乳腺纤维腺瘤；其由增生的腺体和纤维间质构成，属良性肿瘤。"},{"q":"患者，男，48岁。鼻塞、头痛、耳鸣3月余，查体发现左侧颈部扪及无痛性包块，活检为淋巴结内转移性鳞状细胞癌，其原发癌最可能是","o":["肺鳞癌","食管鳞癌","鼻咽部鳞癌","喉鳞癌","口腔鳞癌"],"a":2,"e":"鼻塞、头痛、耳鸣伴颈上部淋巴结转移性鳞癌，原发灶最可能位于鼻咽部；鼻咽癌早期即可发生颈淋巴结转移而原发症状轻微。"},{"q":"某患者血气分析结果如下：pH：7.49，PaCO2：48mmHg，HCO3ˉ：36mmol/L，该酸碱平衡紊乱对机体的影响不包含","o":["心血管系统对儿茶酚胺反应性降低","烦躁不安","神经肌肉应激性增高","血红蛋白氧离曲线左移","低钾血症"],"a":0,"e":"pH7.49、HCO3-36mmol/L提示代谢性碱中毒，碱中毒使氧离曲线左移、神经肌肉应激性增高并致低钾；心血管对儿茶酚胺反应性降低见于酸中毒。"},{"q":"一男性患者出现发热，外周血白细胞增高，脑部CT和MRI均表现为囊壁光滑的环形强化占位灶，周围伴不同程度水肿。最可能的诊断是","o":["流行性脑脊髓膜炎","流行性乙型脑炎","急性支气管炎","小叶性肺炎","脑脓肿"],"a":4,"e":"发热、白细胞增高，影像见囊壁光滑的环形强化灶伴周围水肿，为局限性化脓性炎形成脓腔，即脑脓肿；流脑为脑膜弥漫性病变。"},{"q":"患者，男，50岁。橡胶厂工人，无痛性血尿5月余。膀胱镜检查：膀胱三角区可见一乳头状肿物，宽基底无蒂，质地脆。病理活检诊断为浸润性尿路上皮癌。下列哪种物质与本患者所患肿瘤密切相关","o":["3，4-苯并芘","联苯胺","黄曲霉毒素","苯","多环芳烃"],"a":1,"e":"联苯胺等芳香胺类经肝代谢后由尿排出，在膀胱内长期作用，使橡胶、印染工人膀胱癌高发；该类致癌物与尿路上皮癌密切相关。"},{"q":"患者，男，35岁。突发少尿、血尿和咳血，肾功能检查发现肌酐和尿素氮水平显著升高，尿蛋白++++，血清学检查显示存在抗GBM抗体。经皮肾穿刺检查，其可能出现的肾小球病变是","o":["基底膜显著增厚","新月体形成","系膜增生","基底膜呈“双轨征”","内皮细胞增生"],"a":1,"e":"抗GBM抗体介导II型超敏反应，损伤肾小球基膜并刺激壁层上皮细胞增生，形成新月体，临床表现为肺出血肾炎综合征伴急进性肾衰竭。"},{"q":"患者，女，46岁，颈部淋巴结肿大，手术切除。肿大的淋巴结内可见淡黄色、质软的干酪样坏死，镜下见病灶中心为干酪样坏死，周围为上皮样细胞、朗汉斯巨细胞，再向外为大量淋巴细胞浸润和少量反应性增生的成纤维细胞。该淋巴结的病变是","o":["化脓性炎","纤维素性炎","肉芽肿性炎","浆液性炎","出血性炎"],"a":2,"e":"病灶中心为干酪样坏死，周围为放射状排列的上皮样细胞和朗汉斯巨细胞，外周淋巴细胞浸润，为结核结节，属感染性肉芽肿性炎。"},{"q":"患儿，男，3岁。不小心右手被开水烫伤，皮肤上出现多个水疱，此水疱属于","o":["漏出液","纤维素渗出","浆液性渗出","脓性渗出","以上都有"],"a":2,"e":"Ⅱ度烧伤使血浆渗出并积聚于表皮与真皮之间形成水疱，疱液为浆液性渗出物，含少量蛋白和炎症细胞。"},{"q":"患者静脉注射青霉素后，出现心悸，出汗，面色苍白，脉速而弱，其最有可能发生","o":["过敏性休克","失血性休克失代偿期","感染性休克","神经源性休克","心源性休克"],"a":0,"e":"青霉素作为变应原引起I型超敏反应，组胺等释放使血管扩张、通透性增高，有效循环血量骤降，出现心悸、出汗、面色苍白和脉细弱，即过敏性休克。"},{"q":"患者，男，20岁。部队官兵，在一次抢险救灾中造成全身软组织多处挫伤，请问在他组织损伤修复过程开始于以下哪个阶段","o":["损伤早期","损伤晚期","炎症静止期","炎症活动期","炎症起始期"],"a":0,"e":"修复与炎症几乎同时启动，损伤早期即出现中性粒细胞浸润、巨噬细胞聚集和生长因子释放，为再生与肉芽组织形成创造条件。"},{"q":"某患者，受凉后出现畏寒、“鸡皮疙瘩”，手脚冰冷，皮肤苍白，自测体温37.6℃。请问患者处于发热的哪个时相","o":["体温上升期","高温持续期","体温下降期","体温稳定期","体温变化期"],"a":0,"e":"畏寒、皮肤苍白、起鸡皮疙瘩是皮肤血管收缩和竖毛肌收缩的表现，此时体温调定点上移而产热尚未跟上，属体温上升期。"},{"q":"患者，女，40岁。10年前因乙型肝炎住市传染病医院。近2年来周身乏力，消瘦，常伴牙龈出血，月经量多。近10天腹胀加重，伴少尿。查体：面色黝暗无光泽，巩膜黄染，腹壁静脉曲张明显，移动性浊音阳性。上述症状不提示的临床诊断是","o":["乙型肝炎","门脉高压症","肝功能不全","肝性脑病","肝肾综合症"],"a":3,"e":"乏力、消瘦、出血倾向、黄疸、腹壁静脉曲张及腹水提示肝硬化失代偿和门脉高压，尚无意识障碍等肝性脑病表现。"},{"q":"患儿，1岁。因“脑膜炎”发热 3 天，出现哭闹、烦躁不安、肌肉抽搐等症状。请问这些症状出现的主要原因","o":["发热导致患儿丢失大量水分","患儿中枢神经系统感染","小儿神经系统未发育成熟易导致热惊厥","发热使患儿心率加快","患儿因发热出现不适"],"a":2,"e":"婴幼儿中枢神经系统发育不成熟，兴奋易泛化，发热时易出现惊厥，故感染性发热伴抽搐以热性惊厥解释最为合理。"},{"q":"一患者的甲状腺手术切除标本送病理检查，显微镜下见肿瘤细胞多排列成复杂分支的乳头结构，乳头中心有纤维血管间质，间质内常见呈同心圆状的砂粒体，核染色质少，常呈透明或毛玻璃状，无核仁。该患者最有可能的诊断是","o":["滤泡癌","未分化癌","髓样癌","乳头状癌","甲状腺腺瘤"],"a":3,"e":"肿瘤呈复杂分支乳头，乳头轴心为纤维血管间质并见砂粒体，癌细胞核透明呈毛玻璃状、有核沟，为甲状腺乳头状癌的典型形态。"},{"q":"患者，李某，女，30岁，患慢性肾小球肾炎8年。近年来尿量增多，夜间尤甚。本次因妊娠反应严重，呕吐频繁，进食困难而入院。该病人除可出现缺钾外，还可能出现下列哪项电解质紊乱","o":["低磷血症","高钙血症","高钠血症","高镁血症","低镁血症"],"a":4,"e":"频繁呕吐使消化液大量丢失，镁随之丧失，加之慢性肾小球肾炎的肾小管损伤影响重吸收，故除低钾外还出现低镁血症。"},{"q":"患者，男，28岁。腹痛、腹泻三天，每日排便十余次，初为黏液稀便，后转为黏液脓血便，该患者所患疾病可能为","o":["伤寒","大肠癌","阿米巴痢疾","急性细菌性痢疾","肠真菌病"],"a":3,"e":"起病急，大便由黏液稀便转为黏液脓血便且每日十余次，为志贺菌所致结肠假膜性炎，即急性细菌性痢疾。"},{"q":"患者，男，33岁。患肾结核致左肾功能丧失而切除。标本见肾实质切面有大小不等的虫蚀样缺损，该病理改变称为","o":["空洞","溃疡","窦道","瘘管","囊肿"],"a":0,"e":"肾实质内干酪样坏死物液化后经肾盂、输尿管排出，残留空腔，即空洞；多个空洞融合可使肾只剩空壳、功能丧失。"},{"q":"患者，年轻女性，关节、皮肤、肾反复出现病变，肾活检系弥漫增生型改变，可见苏木素小体。该患者血清检测中具有特征性的阳性抗体是","o":["抗DNA拓扑异构酶-1抗体","抗着丝点抗体","抗双链DNA抗体","抗SS-A抗体","抗HLA抗体"],"a":2,"e":"苏木素小体即狼疮小体，由抗核抗体攻击细胞核形成；SLE患者血清中以抗双链DNA抗体最具特异性，且与肾损害活动性相关。"},{"q":"患者，女，48岁。患风湿性心脏病二尖瓣狭窄6年。近一月来出现呼吸困难，咳嗽、气喘，不能平卧，间断自服平喘药氨茶碱，呼吸困难较前减轻，但出现颈静脉怒张，肝脏肿大，下肢水肿。该患者呼吸困难减轻的最主要原因是","o":["氨茶碱治疗有效","二尖瓣狭窄的程度减轻","在原有左心衰竭的基础上又发生了右心衰竭","合并了二尖瓣关闭不全","合并了主动脉病变"],"a":2,"e":"左心衰竭时肺淤血引起呼吸困难；继发右心衰竭后右心排血减少，肺淤血反而减轻，故呼吸困难缓解而出现体循环淤血表现。"},{"q":"患者因肺癌作肺叶切除手术，若切除3/5肺叶，可能会出现呼吸功能障碍，其机制是","o":["肺阻塞性通气功能障碍","肺限制性通气功能障碍","肺弥散功能障碍","残存的肺泡通气不足","残存的肺泡血流不足"],"a":2,"e":"肺叶切除使肺泡膜面积减少，气体弥散面积不足，虽通气尚可仍出现弥散功能障碍；残存肺组织代偿有限，故术后可发生呼吸功能不全。"},{"q":"患者，男，60岁。40年吸烟史。慢性咳嗽30年，近1月来痰中带血丝。X线检查，显示左肺门处不规则巨大阴影。支气管镜检查，左主支气管黏膜粗糙不平，管腔狭窄。活检病理诊断最可能是","o":["慢性支气管炎","大叶性肺炎","肺炎性假瘤","肺癌","肺结核"],"a":3,"e":"长期吸烟、痰中带血伴肺门肿块、支气管黏膜粗糙及管腔狭窄，符合中央型肺癌，纤维支气管镜活检可确诊。"},{"q":"一位日本老年女性是1945年关岛原子弹爆炸后的幸存者，她可能发生","o":["精神病","神经病","多器官衰竭","应激性溃疡","创伤后应激综合征"],"a":4,"e":"经历重大灾难性事件后长期存在反复重现、警觉性增高和回避等表现，属创伤后应激障碍，为强烈精神创伤后的心理反应。"},{"q":"患者，女，45岁。自觉平素体健，单位常规体检时发现肝功能轻度异常，B超显示肝内少量纤维组织增生。问诊了解到该患者从未注射过乙型肝炎免疫球蛋白，平时喜欢在饭店吃饭。病人最可能的诊断是","o":["脂肪肝","轻度慢性肝炎","中度慢性肝炎","肝硬化","肝癌"],"a":1,"e":"肝功能仅轻度异常、肝内少量纤维组织增生，无门脉高压表现，符合轻度慢性肝炎；其病变以肝细胞水肿、点状坏死伴汇管区炎症和轻度纤维化为主。"},{"q":"某女，6岁。身高150cm, 面部粗糙、手脚增厚增大, 生长较同龄儿童明显快。实验室检查发现GH水平总值较正常值高出10倍，临床诊断为巨人症。请分析GH主要通过下列哪个细胞信号转导途径发挥其生物学效应","o":["JAK-STAT信号转导途径","cAMP-PKA通路","IP3/DAG-PKA通路","受体酪氨酸蛋白激酶（RTK）介导的信号转导途径","NF-κB介导的信号转导途径"],"a":0,"e":"生长激素受体属细胞因子受体超家族，本身无酪氨酸激酶活性，须经JAK-STAT通路转导信号，促进IGF-1生成而发挥促生长作用。"},{"q":"患者，男，40岁。面部及下肢水肿2月余，尿液检查蛋白+++，尿肌酐、尿素氮正常。组织学见肾小球体积增大，肾小球基底膜呈弥漫性增厚，无炎症反应。电镜见基底膜增厚，上皮侧大量小丘状电子致密物沉积。此例肾炎可能是什么类型","o":["系膜增生性肾小球肾炎","膜性肾小球病","急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","IgA肾病"],"a":1,"e":"基膜弥漫增厚、上皮侧见小丘状电子致密物沉积而无炎症细胞浸润，为膜性肾小球病的特征；临床表现为肾病综合征，成人多见。"},{"q":"患者，女，62岁。冠心病病史10年，近日上呼吸道感染在某诊所输液治疗过程中，因速度过快突然出现呼吸困难，咳嗽、咳粉红色泡沫痰。出现此现象最有可能的原因是","o":["上呼吸道感染加重，导致肺循环阻力增大","输液速度过快使血容量急剧增加","交感神经兴奋性增高，外周阻力增大","发生了酸中毒，导致心肌收缩性减弱","缺氧导致心肌供氧不足"],"a":1,"e":"输液过快使血容量骤增，回心血量及左心前负荷加重，原有冠心病心肌收缩力不足，肺静脉压急升而发生急性肺水肿，咳粉红色泡沫痰。"},{"q":"一女性患者，近期出现怕冷、嗜睡、月经周期紊乱、声音嘶哑、便秘，皮肤苍白、发凉、粗糙、非凹陷性水肿，有可能患有","o":["甲亢","甲状腺功能低下","甲状腺功能亢进","慢性淋巴细胞性甲状腺炎","慢性纤维性甲状腺炎"],"a":1,"e":"甲状腺素不足使代谢率降低，出现怕冷、嗜睡、便秘及皮肤苍白发凉、非凹陷性黏液水肿，符合甲状腺功能低下。"},{"q":"患者，女，53岁。体检发现左乳外上象限无痛性肿物，直径2cm左右，活动度差，同侧腋窝触及1枚肿大淋巴结。病理诊断为乳腺浸润性导管癌。本患者可能有下列哪项指标异常","o":["BHD基因突变","BRCA-1基因突变","KIT点突变","L-myc 基因扩增","hst-1过度表达"],"a":1,"e":"BRCA1为抑癌基因，胚系突变使DNA双链修复障碍，携带者终生乳腺癌风险显著增高，且发病年轻、多为三阴性。"},{"q":"患者，女，60岁。高血压病史10年。近半月来，患者疲倦、下肢水肿明显，尿中出现大量泡沫并不易消退。医生建议患者进一步检查，你认为下列哪项检查是不必要的","o":["尿常规","眼底镜","心脏超声","脑CT","肺功能检查"],"a":4,"e":"患者有高血压史并出现蛋白尿、水肿，提示肾损害，应查尿常规、眼底和心脏超声评估靶器官；肺功能与本病无关，属不必要检查。"},{"q":"患者，女，56岁。慢性咳嗽、咳痰3年，每年冬季发作，多持续3～4个月。近一周再次出现咳嗽、咳白黏痰，无发热及呼吸困难。实验室检查：白细胞7.0×109/L，分叶68%，淋巴30%，嗜酸1%，单核1%，尿常规正常，胸片可见双肺纹理增多、紊乱。查肺功能：FEV1/FVC正常。最恰当的诊断是","o":["慢性阻塞性肺疾病","肺结核","支气管哮喘","慢性支气管炎","肺炎"],"a":3,"e":"咳嗽咳痰每年持续3个月、连续2年以上，胸片示肺纹理增多紊乱而FEV1/FVC正常，无气流受限，符合慢性支气管炎。"},{"q":"患者，女性，38岁，因减肥连续服用泻药一周，现感虚弱乏力，偶有直立性眩晕而入院。患者皮肤弹性差，黏膜干燥，血Na+140mmol/L，血浆渗透压295mOsm/L。其发生的水、钠代谢紊乱类型是","o":["等渗性脱水","低渗性脱水","水中毒","水肿","高渗性脱水"],"a":0,"e":"连续服用泻药使肠液大量丢失，而血钠140mmol/L、血浆渗透压295mOsm/L均在正常范围，为等渗性脱水，故有黏膜干燥和直立性眩晕。"},{"q":"患者，男，新生儿。出生后发现面部有一不规则形红斑，红斑突起于皮肤。本病例最可能的诊断是","o":["脂肪瘤","平滑肌瘤","淋巴管瘤","基底细胞癌","血管瘤"],"a":4,"e":"新生儿面部不规则鲜红斑块且隆起于皮肤，为先天性血管畸形，属毛细血管型血管瘤；血管瘤在儿童多见，可随发育增大或自行消退。"},{"q":"死者，女，尸检发现两肾体积缩小，重量减轻，质地硬，皮质变薄，表面呈颗粒状，肾切片观察，均有细动脉玻璃样变性，肾小球纤维化等改变。此患者生前可能患有的疾病是","o":["肾盂肾炎","高血压病","肾小球肾炎","药物中毒","肾癌"],"a":1,"e":"双肾缩小、表面呈细颗粒状、皮质变薄即颗粒性固缩肾，镜下入球动脉玻璃样变、肾小球纤维化，为高血压病所致肾硬化。"},{"q":"患者，男，40岁。因交通意外致外伤出血。急诊接诊检查，神智清，面色苍白，四肢湿冷，心率88次/分，血压105/85mmHg。该患者腹腔内脏微循环变化的特点为","o":["少灌多流、灌多于流","多灌多流、灌少于流","少灌少流、灌少于流","多灌少流、灌多于流","少灌少流、灌多于流"],"a":2,"e":"休克早期交感-肾上腺髓质兴奋，微动脉、微静脉及毛细血管前括约肌均收缩，微循环灌流量减少，呈少灌少流、灌少于流。"},{"q":"某肝性脑病患者血气测定结果为：pH 7.48，仅根据pH的变化，可作出酸碱平衡紊乱类型的诊断为","o":["代偿性碱中毒","代偿性酸中毒","失代偿性碱中毒","失代偿性酸中毒","失代偿性呼吸性碱中毒"],"a":2,"e":"pH7.48高于正常上限，仅凭pH只能判断为失代偿性碱中毒；确定是呼吸性还是代谢性，须结合PaCO2与HCO3-的变化。"},{"q":"某肾衰竭患者放置导尿管2天后，出现发热、腰痛，尿中含有大量白细胞和细菌。血气检查结果为：pH：7.39，PaCO2：19mmHg，HCO3-：11mmol/L，可诊断为","o":["代谢性酸中毒","呼吸性碱中毒","代谢性酸中毒合并代谢性碱中毒","代谢性酸中毒合并呼吸性碱中毒","代谢性碱中毒合并呼吸性碱中毒"],"a":3,"e":"HCO3-11mmol/L明显降低，为代谢性酸中毒；PaCO2 19mmHg显著低于代偿预期，说明通气过度，合并呼吸性碱中毒。"},{"q":"患者，女，60岁。心绞痛病史3年，1年前出现劳力性呼吸困难等症状。近来呼吸困难加重，夜间常不能平卧。查体：颈静脉怒张，心界向两侧扩大，双肺底可闻及湿性啰音，肝脏肿大，双下肢水肿。该患者最可能的诊断是","o":["左心衰竭","右心衰竭","全心衰竭","左房衰竭","右房衰竭"],"a":2,"e":"呼吸困难、双肺底湿啰音提示左心衰竭，颈静脉怒张、肝大和下肢水肿提示右心衰竭，心界向两侧扩大，故为全心衰竭。"},{"q":"患者，男，16岁。左侧下肢内踝肿胀明显1周，约3cm×3cm×2cm范围，高出皮肤，色红、质软，皮温高、有波动感。实验室检查：白细胞计数14、8×109/L，其中中性粒细胞占85%，血培养1周后结果为金黄色葡萄球菌阳性。该病变应诊断为","o":["脓肿","蜂窝织炎","表面化脓","浆液性炎","肉芽肿性炎"],"a":0,"e":"局部红肿热痛伴波动感、中性粒细胞升高，血培养金黄色葡萄球菌阳性，为局限性化脓性炎并形成脓腔，即脓肿；蜂窝织炎无明显脓腔。"},{"q":"患者，男，65岁。慢性肾小球肾炎10余年。因进展为CRF入院，其临床表现中最不可能出现的是","o":["尿量超过2000ml/24h","尿量少于400ml/24h","尿比重1.003~1.030","尿比重1.008~1.012","蛋白尿、血尿和管型尿"],"a":2,"e":"慢性肾衰竭时肾浓缩稀释功能丧失，尿比重固定于1.008~1.012，故不可能出现1.003~1.030的宽幅波动；尿量可多可少，蛋白尿、血尿与管型尿均常见。"},{"q":"患者，男，60岁。近段时间出现乏力、厌食、肝区疼痛加重。肝活检显示，肝组织碎片状坏死，有炎症细胞浸润和毛玻璃样肝细胞，见纤维间隔增生，但肝小叶结构基本保存。患者10年前诊断为急性乙型肝炎。患者现在最可能被诊断为","o":["轻度慢性乙型肝炎","中度慢性乙型肝炎","重度慢性乙型肝炎","门脉性肝硬化","酒精性肝炎"],"a":1,"e":"碎片状坏死明显、纤维间隔增生而肝小叶结构基本保存，符合中度慢性乙型肝炎；轻度者坏死轻微，重度者出现桥接坏死并致小叶结构紊乱。"},{"q":"患儿，男，10岁。2周前患扁桃腺炎，经治疗好转。近2天来出现眼睑水肿，少尿、血尿，尿蛋白（+++），血压升高（150/90mmHg）。患者的临床表现符合","o":["急性肾炎综合征","肾病综合征","慢性肾炎综合征","快速进行性肾炎综合征","无症状性血尿或蛋白尿"],"a":0,"e":"感染后1~2周出现血尿、蛋白尿、少尿、水肿与血压升高，为急性肾炎综合征，由链球菌感染后免疫复合物性肾小球损伤引起。"},{"q":"一尸检标本，见肝脏体积增大，颜色淡黄，光镜下见肝细胞胞浆中出现大小不等的空泡。其最有可能的病理变化是","o":["气球样变","脂肪变","细胞水肿","黏液样变","细胞坏死"],"a":1,"e":"肝细胞胞质内出现大小不等的脂滴空泡，肝体积增大、色淡黄，为肝脂肪变；细胞水肿表现为胞质疏松淡染、细胞肿大而非空泡状脂滴。"},{"q":"患者，男，70岁。反复咳嗽、咳痰3月。痰液脱落细胞学检查镜下见成堆体积大的细胞，细胞核大、深染，染色质粗，可见病理性核分裂象。这些细胞可能是","o":["中性粒细胞","淋巴细胞","癌细胞","鳞状上皮细胞","杯状细胞"],"a":2,"e":"细胞核大深染、染色质粗糙、核浆比增大并见病理性核分裂象，是恶性肿瘤细胞的形态学标志，痰涂片中的这类细胞为癌细胞。"},{"q":"患者，男，23岁。24小时前因车祸引起左下肢胫骨及腓骨开放性、粉碎性骨折，入院清创固定后12小时，出现左小腿及左足青紫、肿胀，患者出现发热和全身不适。次日肿胀加剧，累及左大腿，伤口流出恶臭脓汁，伴有气泡，肿胀区按之有捻发音。左小腿的病变为","o":["干性坏疽","湿性坏疽","气性坏疽","液化性坏死","干酪样坏死"],"a":2,"e":"开放性粉碎性骨折后伤口流出恶臭脓汁、伴气泡溢出，肿胀区按之有捻发音，是产气荚膜梭菌感染所致气性坏疽，属湿性坏疽的特殊类型。"},{"q":"患者，男，68岁。糖尿病史10年。近一年来左下肢行走后疼痛，休息后好转。近两个月左拇趾变黑，皱缩，知觉消失。此种坏死最可能是","o":["固缩坏死","干性坏疽","湿性坏疽","气性坏疽","液化性坏死"],"a":1,"e":"糖尿病患者足趾因动脉闭塞缺血坏死，坏死组织干涸皱缩、呈黑褐色、与健康组织界限清楚，为干性坏疽。"},{"q":"患者，男，73岁。面颊部发现一溃疡2年余。病理检查发现：癌巢由深染的基底细胞样癌细胞构成。该患者的病理诊断是","o":["脂肪瘤","乳头状腺癌","基底细胞癌","血管肉瘤","纤维肉瘤"],"a":2,"e":"癌巢由深染的基底细胞样癌细胞构成并伴溃疡形成，是基底细胞癌的组织学特点；该瘤生长缓慢、极少发生转移。"},{"q":"患儿，男，4岁。于8月前来就诊。高热8小时，抽搐2小时，呕吐一次，体温40℃，血压46/18mmHg，昏睡状，面色苍白，腮腺不大，颈软，四肢紧张，肢冷，腱反射亢进， 皮肤呈花纹状，心肺腹未见异常，实验室检查：WBC：18×109/L，N：0.86，L：0.14, 粪便镜检：WBC：2～8/HP，应首选考虑诊断为","o":["流行性乙型脑炎","中毒性菌痢","腮腺炎脑炎","脑型疟疾","流行性脑脊髓膜炎"],"a":1,"e":"高热、抽搐、休克而脑膜刺激征阴性，粪便仅见少量白细胞，符合中毒性菌痢；乙型脑炎与流脑多有明显的神经系统体征。"},{"q":"患者，男，48岁。20年吸烟史。8年前每当气候转凉便开始咳嗽，痰呈白色黏液样，至天气转暖后症状好转。近一年来咳嗽发作频繁，但痰量减少，为干咳少痰症状。其可能的原因是","o":["支气管扩张","支气管哮喘","长期慢性支气管炎引起支气管黏膜和腺体萎缩","肺癌广泛转移","肺气肿合并慢性肺心病"],"a":2,"e":"长期慢性支气管炎反复损伤使支气管黏膜上皮与腺体萎缩、分泌减少，故由咳白色黏液痰转为干咳少痰。"},{"q":"某患者血氧检查结果是：动脉血氧分压50mmHg（正常为100mmHg），血氧容量20ml/dl（正常为20ml/dl），动脉血氧含量15ml/dl(正常为19ml/dl)，动-静脉氧含量差4ml/dl(正常为5ml/dl)。请问其缺氧类型是哪一种","o":["低张性缺氧","血液型缺氧","循环性缺氧","组织性缺氧","混合型缺氧"],"a":0,"e":"动脉血氧分压明显降低而血氧容量正常、动静脉氧含量差大致正常，为低张性缺氧；血液型者血氧容量降低，循环性者动静脉氧差增大。"},{"q":"脑缺血后，局部增加的物质是","o":["糖原","葡萄糖","ATP","磷酸肌酸","乳酸"],"a":4,"e":"脑缺血使氧化磷酸化受阻，无氧糖酵解增强，乳酸生成增多并在局部堆积，故缺血区乳酸升高。"},{"q":"患者，女，31岁，孕40周。分娩时出现阴道大量流血，注射催产素后仍流血不止。因病情恶化，抢救无效死亡。尸检发现双肺明显水肿、淤血及出血，大部分肺泡壁毛细血管内可见均质、红染的微血栓。其最可能的病理诊断是","o":["败血症","休克","DIC","羊水栓塞","心力衰竭"],"a":2,"e":"产后大出血诱发全身微血管内广泛纤维蛋白性微血栓形成，肺毛细血管内的均质红染血栓是DIC的形态学证据。"},{"q":"一肾功能衰竭患者血气分析可见：pH 7.30，PaCO2 35mmHg，HCO3ˉ 17mmol/L，该酸碱平衡紊乱发生时，机体主要依靠的代偿模式为","o":["蛋白质缓冲系统的作用","肺的调节作用","细胞内外的离子交换","肾的调节作用","碳酸氢盐缓冲系统的作用"],"a":1,"e":"pH 7.30、HCO3-降低而PaCO2已低于正常，提示代谢性酸中毒，机体主要靠肺通气增强排出CO2进行代偿。"},{"q":"患者，男，35岁。有亚急性重型肝炎病史。最近B超显示，肝脏体积缩小，脾脏肿大。患者可能的诊断是","o":["门脉性肝硬化","坏死后性肝硬化","血吸虫性肝硬化","淤血性肝硬化","胆汁性肝硬化"],"a":1,"e":"亚急性重型肝炎后大片坏死区纤维化收缩，形成大小不等的结节与宽阔的纤维间隔，发展为坏死后性肝硬化。"},{"q":"患者，女，40岁。同房有接触性出血病史，阴道镜检查行宫颈活检，镜下见鳞状上皮层下部近2/3的细胞出现异型性，应诊断为","o":["CINI级","CINII级","CINIII级","宫颈浸润癌","宫颈原位癌"],"a":1,"e":"异型细胞累及鳞状上皮下部近2/3层而未达全层，为CINⅡ级；累及下1/3为Ⅰ级，超过2/3或累及全层为Ⅲ级。"},{"q":"患者，男，60岁。在常规体检中查出镜下血尿，CT检查发现右肾上极有一直径7cm的占位病变，该患者最可能患有的疾病是","o":["肾母细胞瘤","血管平滑肌脂肪瘤","肾细胞癌","肾结石","转移性癌"],"a":2,"e":"中老年男性肾上极实性占位伴镜下血尿，最常见为肾细胞癌；肾母细胞瘤见于儿童，血管平滑肌脂肪瘤属良性病变。"},{"q":"在一例79岁老年男性的尸体剖验中，发现其双肾体积变小，包膜皱缩，表面细颗粒状，镜下见散在的肾小球纤维化和玻璃样变，肾小管萎缩伴间质纤维化，细小动脉壁增厚及玻璃样变。该患者生前肾功能检查正常，其肾脏改变最符合的诊断是","o":["糖尿病所致肾小球结节性硬化","过敏性间质性肾炎","慢性肾盂肾炎","良性高血压所致颗粒性固缩肾","肾小球肾炎所致颗粒性固缩肾"],"a":3,"e":"双肾对称缩小、表面细颗粒状，入球动脉玻璃样变致肾小球缺血硬化，为良性高血压引起的原发性颗粒性固缩肾。"},{"q":"患者，女，55岁。对称性手足关节疼痛不适、变形，查体发现皮下结节。取结节活检，镜下见中央为纤维素样坏死，周围呈栅状或放射状排列的上皮样细胞，外围为肉芽组织。该患者的诊断是","o":["类风湿性关节炎","系统性红斑狼疮","风湿性关节炎","炎性疾病","系统性硬化"],"a":0,"e":"皮下结节中央为纤维素样坏死，周围上皮样细胞呈栅状放射状排列，外围肉芽组织，为典型类风湿结节，提示类风湿性关节炎。"},{"q":"患者，男，38岁。反复鼻塞3年。鼻腔镜示中鼻甲有一带蒂的肿物，表面光滑，灰红色，大小为2cm×2cm×1cm。镜下见黏膜上皮及腺体增生，间质水肿，血管扩张充血，有淋巴细胞浸润。该病变最可能是","o":["鼻炎","炎性息肉","炎性假瘤","乳头状瘤","腺瘤"],"a":1,"e":"带蒂、表面光滑的鼻腔肿物，镜下为黏膜上皮与腺体增生伴间质水肿、血管扩张及淋巴细胞浸润，符合炎性息肉。"},{"q":"患者，女，52岁，阴道不规则出血，阴道镜检见子宫颈有菜花样肿物，表面出血坏死。最有可能的诊断是","o":["宫颈糜烂","宫颈息肉","宫颈癌","纳博特囊肿","宫颈肥大"],"a":2,"e":"宫颈菜花样肿物伴表面出血坏死，是宫颈癌的典型大体表现，组织学以鳞状细胞癌最常见，与高危型HPV持续感染有关。"},{"q":"一中年男子在进行健康检查时，X线检查发现右上肺有一直径3cm的圆形阴影，初步考虑肺结核球和支气管肺癌，二者鉴别最有效的方法是","o":["肿瘤标志物检测","痰检查结核杆菌","结节穿刺活检","病史和体格检查","胸部磁共振检查"],"a":2,"e":"肺结核球与周围型肺癌均可呈圆形阴影，痰检阳性率低，经皮穿刺活检取得组织行病理检查是鉴别最可靠的方法。"},{"q":"一男性患者，60岁。20年前被诊断为慢性肝炎，治疗情况不详。近日来，患者出现烦躁不安、睡眠紊乱、记忆力减退，提示该患者可能出现了","o":["肝性脑病","肝硬化","慢性肝炎","肝衰竭","肝肾综合征"],"a":0,"e":"慢性肝病基础上出现烦躁、睡眠紊乱与记忆力减退，是肝性脑病早期的精神神经症状，由血氨等毒性物质蓄积所致。"},{"q":"患者，男，50岁。入院时体温39℃，自觉头痛、腰痛、眼眶痛。口腔黏膜、胸背、腋下出现大小不等的出血点或瘀斑。随着病情的发展，病人退烧，但症状反而加重，继而出现低血压、休克、少尿、无尿及严重出血等症状。应考虑诊断为","o":["伤寒","流行性出血热","泌尿道感染","中毒性休克","病毒性肺炎"],"a":1,"e":"发热、头痛、腰痛、眼眶痛及皮肤瘀点瘀斑，退热后症状反而加重并出现休克、少尿，是流行性出血热的典型病程。"},{"q":"患者，女，40岁。近两年来经常腹泻，有便血史。体检：较消瘦，腹部膨隆，肝未触及，脾脏明显增大，下缘在肋缘下5cm。腹部移动性浊音（+），大便检查出虫卵。考虑诊断为","o":["丝虫病","血吸虫病","门脉性肝硬化","阿米巴病","细菌性痢疾"],"a":1,"e":"流行区接触史伴消瘦、脾明显增大、腹水及粪便查出虫卵，符合血吸虫病所致肝脾病变与窦前性门脉高压。"},{"q":"患者，男，78岁。患急性广泛前壁心肌梗死，入院后常出现夜间阵发性呼吸困难，心率120次/分，两肺底闻及湿性啰音，正确的诊断是急性心肌梗死伴有","o":["支气管哮喘发作","右心衰竭","左心衰竭","全心衰竭","急性心包填塞"],"a":2,"e":"急性广泛前壁心肌梗死使左心室收缩力下降，出现夜间阵发性呼吸困难与肺底湿啰音，为左心衰竭的表现。"},{"q":"患者，男，35岁。间歇性腹泻脓血便二年，乙状结肠镜插入13cm处见到多处3～5mm大小边缘不整的溃疡，较深，溃疡面覆盖灰白色苔状物，肠壁因纤维组织增生、瘢痕形成而增厚变硬。该患者患哪种疾病可能性较大","o":["慢性细菌性痢疾","慢性肠阿米巴病","慢性非特异性溃疡性结肠炎","结肠癌","血吸虫病"],"a":1,"e":"溃疡较深、边缘不整、覆灰白苔，肠壁因纤维增生而增厚变硬，符合慢性肠阿米巴病；菌痢溃疡多表浅呈地图状。"},{"q":"患者，男，49岁。超声诊断肝脂肪变，其发生的原因中最不可能包括的是","o":["缺氧","慢性乙醇中毒","糖尿病","高血压","高脂饮食"],"a":3,"e":"肝脂肪变的常见原因包括缺氧、慢性乙醇中毒、糖尿病与高脂饮食；高血压本身不引起肝细胞脂质蓄积。"},{"q":"死者，老年男性，尸检见肺组织内散在多个小实变区。病理诊断为小叶性肺炎，细支气管壁浸润的炎细胞应为","o":["中性粒细胞","嗜酸性粒细胞","淋巴细胞和浆细胞","巨噬细胞","多核巨细胞"],"a":0,"e":"小叶性肺炎属化脓性炎，细支气管壁及肺泡腔内浸润的炎细胞以中性粒细胞为主，故病灶呈化脓性实变。"},{"q":"患者，男，28岁。右上腹胀痛3个月，黄疸2周，有大量饮酒史。转氨酶轻度升高，B超显示肝脏轻度肿大。肝活检显示，肝细胞脂肪变性，门管区有炎症细胞浸润。患者可能的诊断是","o":["甲型病毒性肝炎","乙型病毒性肝炎","丙型病毒性肝炎","丁型病毒性肝炎","酒精性肝炎"],"a":4,"e":"长期大量饮酒史伴肝细胞脂肪变性、门管区炎症细胞浸润及转氨酶轻度升高，符合酒精性肝炎。"},{"q":"患者，女，13岁。近1周来高热、咳嗽。心率110次/分，偶发期前收缩。全血细胞分析示WBC：10×109/L，中性粒细胞0.56，淋巴细胞0.38。初步诊断为心肌炎。患者心肌间质最可能发生浸润的炎细胞是","o":["淋巴细胞和单核细胞","嗜酸性粒细胞和中性粒细胞","单核细胞和中性粒细胞","中性粒细胞和淋巴细胞","单核细胞和浆细胞"],"a":0,"e":"病毒性心肌炎以淋巴细胞、单核细胞浸润为主并伴心肌细胞变性坏死；中性粒细胞浸润多见于细菌性心肌炎。"},{"q":"16岁男性患者，被诊断为胰岛素依赖性糖尿病，其主要病变的细胞是","o":["胰岛D细胞","胰岛A细胞","胰岛B细胞","心肌细胞","肝细胞"],"a":2,"e":"1型糖尿病为胰岛B细胞受自身免疫破坏，胰岛素分泌绝对不足，故主要受损的细胞是胰岛B细胞。"}];
